#!/usr/bin/env python3
"""Foundry Smart Contract Security Agent.

Pre-deployment audit orchestrator for a Foundry project. Runs static analysis
(Slither, Aderyn), optional symbolic execution (Mythril), Foundry tests/coverage,
and a key-leak scan, then aggregates everything into a single JSON report with a
PASS/FAIL deploy gate.

Design constraints (mirrors the upstream repo's style, hardened):
  - subprocess always called with an ARGUMENT LIST, never shell=True
  - no outbound network calls; every tool runs locally on local source
  - every external tool guarded by timeout and graceful degradation if absent
  - read-only with respect to the project (only writes the report file)
"""

import os
import re
import json
import shutil
import argparse
import logging
import subprocess
from collections import defaultdict
from datetime import datetime, timezone

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

SWC_REGISTRY = {
    "SWC-101": "Integer Overflow and Underflow",
    "SWC-104": "Unchecked Call Return Value",
    "SWC-105": "Unprotected Ether Withdrawal",
    "SWC-106": "Unprotected SELFDESTRUCT",
    "SWC-107": "Reentrancy",
    "SWC-110": "Assert Violation",
    "SWC-112": "Delegatecall to Untrusted Callee",
    "SWC-113": "DoS with Failed Call",
    "SWC-114": "Transaction Order Dependence (front-running)",
    "SWC-115": "Authorization through tx.origin",
    "SWC-116": "Block values as a proxy for time",
    "SWC-120": "Weak Sources of Randomness",
    "SWC-128": "DoS with Block Gas Limit",
}

SEVERITY_RANK = {"critical": 0, "high": 1, "medium": 2, "low": 3, "informational": 4, "optimization": 5}

# Directories that are dependencies / build output, not the audited code.
SKIP_DIRS = {"lib", "out", "cache", "node_modules", ".git", "broadcast", "artifacts"}

# A raw 32-byte hex private key (with or without 0x). High-precision signal: a
# 64-hex literal in source is almost always a key. Broader secret detection
# (mnemonics, API tokens, generic secrets) is intentionally delegated to gitleaks
# (see references/secure-deployment-and-keys.md) rather than reinvented noisily here.
PRIVKEY_RE = re.compile(r"\b(0x)?[0-9a-fA-F]{64}\b")


def _which(tool):
    return shutil.which(tool) is not None


def _run(cmd, timeout):
    """Run a command (list args), return (returncode, stdout, stderr). Never raises."""
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        logger.warning("Timeout: %s", " ".join(cmd))
        return 124, "", "timeout"
    except FileNotFoundError:
        return 127, "", "not found"


# --------------------------------------------------------------------------- #
# Static analysis
# --------------------------------------------------------------------------- #
def run_slither(project):
    if not _which("slither"):
        logger.warning("slither not installed - skipping static analysis")
        return None
    rc, out, err = _run(["slither", project, "--json", "-"], timeout=300)
    # Slither exits non-zero when it finds issues; JSON still lands on stdout.
    if not out:
        logger.error("slither produced no JSON (%s)", err.strip()[:200])
        return {}
    try:
        return json.loads(out)
    except json.JSONDecodeError:
        logger.error("slither JSON parse failed")
        return {}


def analyze_slither(slither_output):
    findings, by_severity, by_detector = [], defaultdict(int), defaultdict(int)
    for det in (slither_output or {}).get("results", {}).get("detectors", []):
        severity = det.get("impact", "informational").lower()
        by_severity[severity] += 1
        name = det.get("check", "unknown")
        by_detector[name] += 1
        loc = ""
        elems = det.get("elements", [])
        if elems:
            sm = elems[0].get("source_mapping", {})
            lines = sm.get("lines") or [0]
            loc = f"{sm.get('filename_short', '')}:L{lines[0]}"
        findings.append({
            "source": "slither", "detector": name, "severity": severity,
            "confidence": det.get("confidence", ""), "location": loc,
            "description": (det.get("description", "") or "").strip()[:240],
        })
    return {
        "total": len(findings),
        "by_severity": dict(by_severity),
        "top_detectors": dict(sorted(by_detector.items(), key=lambda x: -x[1])[:15]),
        "findings": sorted(findings, key=lambda f: SEVERITY_RANK.get(f["severity"], 9)),
    }


def run_aderyn(project):
    if not _which("aderyn"):
        logger.info("aderyn not installed - skipping (recommended: cargo install aderyn)")
        return None
    report = os.path.join(project, "aderyn-report.json")
    rc, out, err = _run(["aderyn", project, "-o", report], timeout=300)
    try:
        with open(report) as fh:
            data = json.load(fh)
        return data
    except (OSError, json.JSONDecodeError):
        logger.error("aderyn report not readable")
        return {}


def analyze_aderyn(aderyn_output):
    findings, by_severity = [], defaultdict(int)
    if not aderyn_output:
        return {"total": 0, "by_severity": {}, "findings": []}
    for sev_key, sev in (("high_issues", "high"), ("low_issues", "low")):
        block = aderyn_output.get(sev_key, {}) or {}
        for issue in block.get("issues", []) if isinstance(block, dict) else []:
            by_severity[sev] += 1
            inst = (issue.get("instances") or [{}])[0]
            loc = f"{inst.get('contract_path', '')}:L{inst.get('line_no', 0)}"
            findings.append({
                "source": "aderyn", "detector": issue.get("title", ""), "severity": sev,
                "location": loc, "description": (issue.get("description", "") or "").strip()[:240],
            })
    return {
        "total": len(findings),
        "by_severity": dict(by_severity),
        "findings": sorted(findings, key=lambda f: SEVERITY_RANK.get(f["severity"], 9)),
    }


# --------------------------------------------------------------------------- #
# Symbolic execution (optional)
# --------------------------------------------------------------------------- #
def run_mythril(target, timeout):
    if not _which("myth"):
        logger.info("mythril not installed - skipping symbolic execution")
        return None
    rc, out, err = _run(
        ["myth", "analyze", target, "--execution-timeout", str(timeout), "-o", "json"],
        timeout=timeout + 60,
    )
    if not out:
        return {}
    try:
        return json.loads(out)
    except json.JSONDecodeError:
        logger.error("mythril JSON parse failed")
        return {}


def analyze_mythril(mythril_output):
    findings, by_swc = [], defaultdict(int)
    for issue in (mythril_output or {}).get("issues", []):
        swc = f"SWC-{issue.get('swc-id')}" if issue.get("swc-id") else "unknown"
        by_swc[swc] += 1
        findings.append({
            "source": "mythril", "swc_id": swc,
            "swc_title": SWC_REGISTRY.get(swc, issue.get("title", "")),
            "severity": issue.get("severity", "Medium").lower(),
            "location": f"{issue.get('contract', '')}:L{issue.get('lineno', 0)}",
            "description": (issue.get("description", "") or "").strip()[:240],
        })
    return {"total": len(findings), "by_swc": dict(by_swc), "findings": findings}


# --------------------------------------------------------------------------- #
# Foundry tests + coverage
# --------------------------------------------------------------------------- #
def run_forge_tests(project):
    if not _which("forge"):
        logger.warning("forge not installed - skipping tests")
        return {"available": False}
    rc, out, err = _run(["forge", "test"], timeout=900)
    text = out + err
    passed = sum(int(n) for n in re.findall(r"(\d+)\s+passed", text))
    failed = sum(int(n) for n in re.findall(r"(\d+)\s+failed", text))
    return {"available": True, "exit_code": rc, "passed": passed,
            "failed": failed, "all_passed": rc == 0}


def run_forge_coverage(project):
    if not _which("forge"):
        return {"available": False}
    rc, out, err = _run(["forge", "coverage", "--report", "summary"], timeout=1200)
    m = re.search(r"^\|\s*Total\s*\|\s*([\d.]+)%", out, re.M)
    lines_pct = float(m.group(1)) if m else None
    return {"available": True, "lines_pct": lines_pct}


# --------------------------------------------------------------------------- #
# Key hygiene
# --------------------------------------------------------------------------- #
def scan_key_leaks(project):
    """Heuristic scan for plaintext private keys / mnemonics in source-controlled files."""
    hits = []
    for root, dirs, files in os.walk(project):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for f in files:
            # Match source/config files plus all dotenv variants (.env, .env.local, .env.prod...)
            if not (f.endswith((".sol", ".env", ".json", ".js", ".ts", ".toml", ".txt", ".md", ".sh", ".yaml", ".yml"))
                    or f.startswith(".env")):
                continue
            path = os.path.join(root, f)
            try:
                with open(path, encoding="utf-8", errors="ignore") as fh:
                    content = fh.read()
            except OSError:
                continue
            for m in PRIVKEY_RE.finditer(content):
                # Exclude the well-known Anvil/Hardhat test mnemonic-derived keys & all-zero.
                val = m.group(0).lower().removeprefix("0x")
                if val == "0" * 64 or "test test test" in content[max(0, m.start() - 80):m.start()]:
                    continue
                hits.append({"file": os.path.relpath(path, project), "type": "possible_private_key"})
                break
    return {"leaked_secret_candidates": len(hits), "hits": hits[:20],
            "note": "high-precision private-key scan only; run gitleaks for full secret coverage"}


# --------------------------------------------------------------------------- #
# Aggregation + gate
# --------------------------------------------------------------------------- #
def deduplicate(*finding_lists):
    seen, combined = set(), []
    for lst in finding_lists:
        for f in lst:
            key = (f.get("location", ""), f.get("detector", f.get("swc_id", "")))
            if key not in seen:
                seen.add(key)
                combined.append(f)
    return combined


def build_report(project, slither, aderyn, mythril, tests, coverage, keys, min_coverage):
    combined = deduplicate(slither["findings"], aderyn["findings"], mythril["findings"])
    crit_high = sum(1 for f in combined if f.get("severity") in ("critical", "high"))

    gate_fail = []
    if crit_high > 0:
        gate_fail.append(f"{crit_high} high/critical static finding(s)")
    if tests.get("available") and not tests.get("all_passed"):
        gate_fail.append(f"{tests.get('failed', '?')} failing test(s)")
    if keys["leaked_secret_candidates"] > 0:
        gate_fail.append(f"{keys['leaked_secret_candidates']} possible leaked secret(s)")
    cov = coverage.get("lines_pct")
    if cov is not None and cov < min_coverage:
        gate_fail.append(f"line coverage {cov}% < {min_coverage}% threshold")

    return {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "project": os.path.abspath(project),
        "static_analysis": {
            "slither": {"total": slither["total"], "by_severity": slither["by_severity"],
                        "top_detectors": slither["top_detectors"]},
            "aderyn": {"total": aderyn["total"], "by_severity": aderyn["by_severity"]},
        },
        "symbolic_execution": {"mythril": {"total": mythril["total"], "by_swc": mythril.get("by_swc", {})}},
        "testing": {"forge_test": tests, "coverage": coverage},
        "key_hygiene": keys,
        "combined_findings": len(combined),
        "critical_high_findings": crit_high,
        "deploy_gate": "PASS" if not gate_fail else "FAIL",
        "gate_failures": gate_fail,
        "findings": combined[:40],
    }


def main():
    ap = argparse.ArgumentParser(description="Foundry Smart Contract Security Audit Agent")
    ap.add_argument("--project", default=".", help="Path to the Foundry project root")
    ap.add_argument("--mythril", metavar="FILE", help="Run Mythril symbolic execution on this .sol file")
    ap.add_argument("--mythril-timeout", type=int, default=300)
    ap.add_argument("--min-coverage", type=float, default=80.0, help="Min line coverage %% for PASS")
    ap.add_argument("--output", default="audit-report.json")
    args = ap.parse_args()

    logger.info("Auditing Foundry project: %s", os.path.abspath(args.project))
    slither = analyze_slither(run_slither(args.project))
    aderyn = analyze_aderyn(run_aderyn(args.project))
    mythril = analyze_mythril(run_mythril(args.mythril, args.mythril_timeout) if args.mythril else {})
    tests = run_forge_tests(args.project)
    coverage = run_forge_coverage(args.project)
    keys = scan_key_leaks(args.project)

    report = build_report(args.project, slither, aderyn, mythril, tests, coverage, keys, args.min_coverage)
    with open(args.output, "w") as fh:
        json.dump(report, fh, indent=2, default=str)
    logger.info("Audit: %d findings (%d high/critical) | gate=%s",
                report["combined_findings"], report["critical_high_findings"], report["deploy_gate"])
    if report["gate_failures"]:
        logger.warning("Gate failures: %s", "; ".join(report["gate_failures"]))
    print(json.dumps(report, indent=2, default=str))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Agent for auditing GCP IAM permissions using google-cloud libraries."""

import json
import argparse
from datetime import datetime

from google.cloud import asset_v1
from google.cloud import resourcemanager_v3


def search_iam_policies(scope, query=""):
    """Search IAM policies across the GCP organization."""
    client = asset_v1.AssetServiceClient()
    request = asset_v1.SearchAllIamPoliciesRequest(scope=scope, query=query, page_size=500)
    results = []
    for result in client.search_all_iam_policies(request=request):
        for binding in result.policy.bindings:
            results.append({
                "resource": result.resource,
                "role": binding.role,
                "members": list(binding.members),
            })
    return results


def find_primitive_roles(scope):
    """Find all IAM bindings using primitive roles (Owner, Editor)."""
    query = "policy:roles/owner OR policy:roles/editor"
    return search_iam_policies(scope, query)


def find_public_bindings(scope):
    """Find resources accessible to allUsers or allAuthenticatedUsers."""
    query = "policy:allUsers OR policy:allAuthenticatedUsers"
    return search_iam_policies(scope, query)


def list_service_accounts(project_id):
    """List all service accounts in a project with key info."""
    from google.cloud import iam_admin_v1
    client = iam_admin_v1.IAMClient()
    request = iam_admin_v1.ListServiceAccountsRequest(name=f"projects/{project_id}")
    accounts = []
    for sa in client.list_service_accounts(request=request):
        sa_info = {
            "email": sa.email,
            "display_name": sa.display_name,
            "disabled": sa.disabled,
            "user_managed_keys": [],
        }
        key_request = iam_admin_v1.ListServiceAccountKeysRequest(
            name=sa.name,
            key_types=[iam_admin_v1.ListServiceAccountKeysRequest.KeyType.USER_MANAGED],
        )
        keys = client.list_service_account_keys(request=key_request)
        for key in keys.keys:
            sa_info["user_managed_keys"].append({
                "name": key.name.split("/")[-1],
                "valid_after": str(key.valid_after_time),
                "valid_before": str(key.valid_before_time),
            })
        accounts.append(sa_info)
    return accounts


def get_project_iam_policy(project_id):
    """Get IAM policy for a specific project."""
    client = resourcemanager_v3.ProjectsClient()
    request = {"resource": f"projects/{project_id}"}
    policy = client.get_iam_policy(request=request)
    bindings = []
    for binding in policy.bindings:
        bindings.append({"role": binding.role, "members": list(binding.members)})
    return bindings


def analyze_permissions(scope, identity):
    """Analyze what resources an identity can access."""
    client = asset_v1.AssetServiceClient()
    request = asset_v1.AnalyzeIamPolicyRequest(
        analysis_query=asset_v1.IamPolicyAnalysisQuery(
            scope=scope,
            identity_selector=asset_v1.IamPolicyAnalysisQuery.IdentitySelector(
                identity=identity
            ),
        )
    )
    response = client.analyze_iam_policy(request=request)
    results = []
    for entry in response.main_analysis.analysis_results:
        for acl in entry.access_control_lists:
            resources = [r.full_resource_name for r in acl.resources]
            accesses = [a.role for a in acl.accesses]
            results.append({"resources": resources, "roles": accesses})
    return results


def classify_risk(bindings):
    """Classify risk for IAM bindings."""
    critical = []
    high = []
    for b in bindings:
        role = b.get("role", "")
        members = b.get("members", [])
        if "allUsers" in members or "allAuthenticatedUsers" in members:
            critical.append(b)
        elif role in ("roles/owner", "roles/editor"):
            for m in members:
                if "serviceAccount" in m:
                    critical.append(b)
                    break
            else:
                high.append(b)
    return {"critical": critical, "high": high}


def main():
    parser = argparse.ArgumentParser(description="GCP IAM Permissions Audit Agent")
    parser.add_argument("--org-id", help="GCP Organization ID")
    parser.add_argument("--project-id", help="GCP Project ID")
    parser.add_argument("--identity", help="Identity to analyze (user:email or serviceAccount:email)")
    parser.add_argument("--output", default="gcp_iam_audit.json")
    parser.add_argument("--action", choices=[
        "primitive_roles", "public_access", "service_accounts",
        "analyze_identity", "full_audit"
    ], default="full_audit")
    args = parser.parse_args()

    scope = f"organizations/{args.org_id}" if args.org_id else f"projects/{args.project_id}"
    report = {"audit_date": datetime.utcnow().isoformat(), "scope": scope, "findings": {}}

    if args.action in ("primitive_roles", "full_audit"):
        primitives = find_primitive_roles(scope)
        report["findings"]["primitive_roles"] = primitives
        print(f"[+] Primitive role bindings: {len(primitives)}")

    if args.action in ("public_access", "full_audit"):
        public = find_public_bindings(scope)
        report["findings"]["public_access"] = public
        print(f"[+] Public access bindings: {len(public)}")

    if args.action in ("service_accounts", "full_audit") and args.project_id:
        sas = list_service_accounts(args.project_id)
        report["findings"]["service_accounts"] = sas
        keys_count = sum(len(sa["user_managed_keys"]) for sa in sas)
        print(f"[+] Service accounts: {len(sas)}, user-managed keys: {keys_count}")

    if args.action == "analyze_identity" and args.identity:
        access = analyze_permissions(scope, args.identity)
        report["findings"]["identity_access"] = access
        print(f"[+] Resources accessible by {args.identity}: {len(access)}")

    with open(args.output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Agent for auditing Kubernetes cluster RBAC configurations."""

import os
import json
import argparse
from datetime import datetime

from kubernetes import client, config


def load_kube_config(kubeconfig=None, context=None):
    """Load Kubernetes configuration."""
    if kubeconfig:
        config.load_kube_config(config_file=kubeconfig, context=context)
    else:
        try:
            config.load_incluster_config()
        except config.ConfigException:
            config.load_kube_config(context=context)


def list_cluster_roles_with_wildcards():
    """Find ClusterRoles with wildcard verb or resource permissions."""
    rbac = client.RbacAuthorizationV1Api()
    roles = rbac.list_cluster_role()
    risky = []
    for role in roles.items:
        for rule in role.rules or []:
            verbs = rule.verbs or []
            resources = rule.resources or []
            if "*" in verbs or "*" in resources:
                risky.append({
                    "name": role.metadata.name,
                    "verbs": verbs,
                    "resources": resources,
                    "api_groups": rule.api_groups or [],
                })
    return risky


def list_secret_access_roles():
    """Find ClusterRoles that can read secrets."""
    rbac = client.RbacAuthorizationV1Api()
    roles = rbac.list_cluster_role()
    results = []
    for role in roles.items:
        for rule in role.rules or []:
            resources = rule.resources or []
            verbs = rule.verbs or []
            if ("secrets" in resources or "*" in resources) and \
               ("get" in verbs or "list" in verbs or "*" in verbs):
                if not role.metadata.name.startswith("system:"):
                    results.append({
                        "role": role.metadata.name,
                        "verbs": verbs,
                        "resources": resources,
                    })
    return results


def list_cluster_admin_bindings():
    """Find all ClusterRoleBindings that grant cluster-admin."""
    rbac = client.RbacAuthorizationV1Api()
    bindings = rbac.list_cluster_role_binding()
    results = []
    for binding in bindings.items:
        if binding.role_ref.name == "cluster-admin":
            subjects = []
            for s in binding.subjects or []:
                subjects.append({
                    "kind": s.kind,
                    "name": s.name,
                    "namespace": s.namespace or "cluster-wide",
                })
            results.append({
                "binding": binding.metadata.name,
                "subjects": subjects,
            })
    return results


def find_dangerous_bindings():
    """Find bindings granting access to system:authenticated or system:unauthenticated."""
    rbac = client.RbacAuthorizationV1Api()
    bindings = rbac.list_cluster_role_binding()
    dangerous = []
    for binding in bindings.items:
        for s in binding.subjects or []:
            if s.name in ("system:authenticated", "system:unauthenticated"):
                dangerous.append({
                    "binding": binding.metadata.name,
                    "role": binding.role_ref.name,
                    "subject": s.name,
                })
    return dangerous


def audit_service_account_tokens():
    """Find pods with automounted service account tokens."""
    v1 = client.CoreV1Api()
    pods = v1.list_pod_for_all_namespaces()
    risky_pods = []
    for pod in pods.items:
        spec = pod.spec
        sa = spec.service_account_name or "default"
        automount = spec.automount_service_account_token
        if automount is not False and sa != "default":
            risky_pods.append({
                "namespace": pod.metadata.namespace,
                "pod": pod.metadata.name,
                "service_account": sa,
                "automount": True,
            })
    return risky_pods


def find_privileged_containers():
    """Find containers running as privileged or root."""
    v1 = client.CoreV1Api()
    pods = v1.list_pod_for_all_namespaces()
    privileged = []
    for pod in pods.items:
        for container in pod.spec.containers or []:
            sc = container.security_context
            if sc:
                is_privileged = getattr(sc, "privileged", False)
                run_as_root = getattr(sc, "run_as_user", None) == 0
                if is_privileged or run_as_root:
                    privileged.append({
                        "namespace": pod.metadata.namespace,
                        "pod": pod.metadata.name,
                        "container": container.name,
                        "privileged": is_privileged,
                        "run_as_root": run_as_root,
                    })
    return privileged


def main():
    parser = argparse.ArgumentParser(description="Kubernetes RBAC Audit Agent")
    parser.add_argument("--kubeconfig", default=os.getenv("KUBECONFIG"))
    parser.add_argument("--context", help="Kubernetes context to use")
    parser.add_argument("--output", default="k8s_rbac_audit.json")
    parser.add_argument("--action", choices=[
        "wildcards", "secrets", "cluster_admin", "dangerous",
        "tokens", "privileged", "full_audit"
    ], default="full_audit")
    args = parser.parse_args()

    load_kube_config(args.kubeconfig, args.context)
    report = {"audit_date": datetime.utcnow().isoformat(), "findings": {}}

    if args.action in ("wildcards", "full_audit"):
        wildcards = list_cluster_roles_with_wildcards()
        report["findings"]["wildcard_roles"] = wildcards
        print(f"[+] Wildcard ClusterRoles: {len(wildcards)}")

    if args.action in ("secrets", "full_audit"):
        secret_roles = list_secret_access_roles()
        report["findings"]["secret_access_roles"] = secret_roles
        print(f"[+] Roles with secret access: {len(secret_roles)}")

    if args.action in ("cluster_admin", "full_audit"):
        admins = list_cluster_admin_bindings()
        report["findings"]["cluster_admin_bindings"] = admins
        total_subjects = sum(len(a["subjects"]) for a in admins)
        print(f"[+] cluster-admin bindings: {len(admins)} ({total_subjects} subjects)")

    if args.action in ("dangerous", "full_audit"):
        danger = find_dangerous_bindings()
        report["findings"]["dangerous_bindings"] = danger
        print(f"[+] Dangerous bindings: {len(danger)}")

    if args.action in ("tokens", "full_audit"):
        tokens = audit_service_account_tokens()
        report["findings"]["automounted_tokens"] = tokens
        print(f"[+] Pods with automounted tokens: {len(tokens)}")

    if args.action in ("privileged", "full_audit"):
        priv = find_privileged_containers()
        report["findings"]["privileged_containers"] = priv
        print(f"[+] Privileged containers: {len(priv)}")

    with open(args.output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# For authorized MCP server auditing only. Do not scan servers you do not control
# or lack written permission to assess.
"""MCP tool-poisoning audit agent.

Two modes:
  static  -- run Invariant Labs mcp-scan over an MCP config and parse results,
             plus a local heuristic scan of tool descriptions in the config.
  enum    -- launch a stdio MCP server, enumerate tools, and heuristically flag
             poisoned descriptions (hidden instructions, smuggled unicode).

Examples:
  python agent.py static --config ~/.cursor/mcp.json
  python agent.py enum --command node --args ./suspect-mcp-server.js
"""
import argparse
import json
import re
import shutil
import subprocess
import sys
from datetime import datetime, timezone

# Heuristics for instructions aimed at the assistant inside a tool description.
POISON_PATTERNS = [
    r"do not (tell|inform|mention to) the user",
    r"ignore (previous|prior|all) instructions",
    r"<important>|<system>|\[system\]",
    r"read .*(\.ssh|id_rsa|\.env|credentials|passwd)",
    r"(send|exfiltrate|post) .* to https?://",
    r"before (using|calling) (this|any) tool,? (you must|always)",
    r"call (the )?\w+ tool (first|before)",
]
SMUGGLE = re.compile(r"[​-‏‪-‮⁠-⁯\U000e0000-\U000e007f]")


def heuristic_flags(description: str):
    flags = []
    low = (description or "").lower()
    for pat in POISON_PATTERNS:
        if re.search(pat, low):
            flags.append(f"pattern:{pat}")
    if SMUGGLE.search(description or ""):
        flags.append("unicode-smuggling")
    if len(description or "") > 1500:
        flags.append("oversized-description")
    return flags


def run_static(args):
    findings = {"ts": datetime.now(timezone.utc).isoformat(),
                "config": args.config, "atlas": "AML.T0010", "scanner": None,
                "heuristic": []}

    # 1. Invoke mcp-scan if available
    runner = shutil.which("uvx") or shutil.which("mcp-scan")
    if runner:
        cmd = ([runner, "mcp-scan@latest", "--json", args.config]
               if "uvx" in runner else [runner, "--json", args.config])
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=240)
            try:
                findings["scanner"] = json.loads(res.stdout)
            except json.JSONDecodeError:
                findings["scanner"] = {"raw": res.stdout[:4000], "stderr": res.stderr[:1000]}
        except subprocess.TimeoutExpired:
            findings["scanner"] = {"error": "mcp-scan timed out"}
    else:
        findings["scanner"] = {"error": "uvx/mcp-scan not found; install uv: "
                                        "curl -LsSf https://astral.sh/uv/install.sh | sh"}

    # 2. Local heuristic scan of any descriptions embedded in the config
    try:
        with open(args.config, encoding="utf-8") as fh:
            cfg = json.load(fh)
        for desc in _walk_descriptions(cfg):
            f = heuristic_flags(desc)
            if f:
                findings["heuristic"].append({"flags": f, "snippet": desc[:200]})
    except (OSError, json.JSONDecodeError) as exc:
        findings["heuristic"].append({"error": str(exc)})

    print(json.dumps(findings, indent=2))
    return findings


def _walk_descriptions(obj):
    """Yield any 'description' string values found anywhere in a nested config."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == "description" and isinstance(v, str):
                yield v
            else:
                yield from _walk_descriptions(v)
    elif isinstance(obj, list):
        for item in obj:
            yield from _walk_descriptions(item)


def run_enum(args):
    try:
        import asyncio
        from mcp import ClientSession, StdioServerParameters
        from mcp.client.stdio import stdio_client
    except ImportError:
        print("Install: pip install mcp", file=sys.stderr)
        sys.exit(1)

    async def _enum():
        params = StdioServerParameters(command=args.command, args=args.args or [])
        out = {"ts": datetime.now(timezone.utc).isoformat(),
               "server": f"{args.command} {' '.join(args.args or [])}",
               "atlas": "AML.T0010", "tools": []}
        async with stdio_client(params) as (r, w):
            async with ClientSession(r, w) as s:
                await s.initialize()
                tools = await s.list_tools()
                for t in tools.tools:
                    flags = heuristic_flags(t.description or "")
                    out["tools"].append({
                        "name": t.name,
                        "desc_len": len(t.description or ""),
                        "flags": flags,
                        "verdict": "POISONED?" if flags else "clean",
                    })
        print(json.dumps(out, indent=2))
        return out

    try:
        asyncio.run(_enum())
    except Exception as exc:  # connection/protocol errors
        print(f"[!] MCP enumeration failed: {exc}", file=sys.stderr)
        sys.exit(2)


def main():
    ap = argparse.ArgumentParser(description="MCP tool-poisoning audit agent")
    sub = ap.add_subparsers(dest="mode", required=True)

    ps = sub.add_parser("static", help="Run mcp-scan + heuristic scan on a config")
    ps.add_argument("--config", required=True, help="Path to MCP config JSON")

    pe = sub.add_parser("enum", help="Enumerate tools from a stdio MCP server")
    pe.add_argument("--command", required=True, help="Server launch command, e.g. node")
    pe.add_argument("--args", nargs="*", help="Arguments to the server command")

    args = ap.parse_args()
    if args.mode == "static":
        run_static(args)
    else:
        run_enum(args)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Agent for auditing Terraform infrastructure for security misconfigurations."""

import json
import argparse
import subprocess
from datetime import datetime


def run_checkov(terraform_dir, output_format="json"):
    """Run Checkov static analysis on Terraform code."""
    cmd = ["checkov", "-d", terraform_dir, "--framework", "terraform", "--output", output_format, "--compact"]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    if output_format == "json":
        try:
            return json.loads(result.stdout)
        except json.JSONDecodeError:
            return {"raw_output": result.stdout, "error": result.stderr}
    return result.stdout


def run_checkov_on_plan(plan_json_path):
    """Run Checkov on a Terraform plan JSON file for accurate analysis."""
    cmd = ["checkov", "-f", plan_json_path, "--framework", "terraform_plan", "--output", "json"]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return {"raw_output": result.stdout}


def run_tfsec(terraform_dir, min_severity="HIGH"):
    """Run tfsec Terraform security scanner."""
    cmd = ["tfsec", terraform_dir, "--format", "json", "--minimum-severity", min_severity]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return {"raw_output": result.stdout}


def parse_checkov_results(checkov_output):
    """Parse Checkov output and extract failed checks with details."""
    findings = []
    if isinstance(checkov_output, list):
        checks = checkov_output
    elif isinstance(checkov_output, dict):
        checks = checkov_output.get("results", {}).get("failed_checks", [])
    else:
        return findings
    for check in checks:
        if isinstance(check, dict):
            findings.append({
                "check_id": check.get("check_id", ""),
                "check_name": check.get("check_result", {}).get("check", {}).get("name", check.get("name", "")),
                "resource": check.get("resource", ""),
                "file": check.get("file_path", ""),
                "line": check.get("file_line_range", []),
                "severity": check.get("severity", "UNKNOWN"),
                "guideline": check.get("guideline", ""),
            })
    return findings


def parse_tfsec_results(tfsec_output):
    """Parse tfsec output and extract findings."""
    findings = []
    results = tfsec_output.get("results", [])
    if results is None:
        return findings
    for r in results:
        findings.append({
            "rule_id": r.get("rule_id", ""),
            "description": r.get("description", ""),
            "severity": r.get("severity", ""),
            "resource": r.get("resource", ""),
            "location": f"{r.get('location', {}).get('filename', '')}:{r.get('location', {}).get('start_line', '')}",
            "resolution": r.get("resolution", ""),
        })
    return findings


def scan_tf_plan_for_issues(plan_json_path):
    """Directly scan a Terraform plan JSON for common security issues."""
    with open(plan_json_path) as f:
        plan = json.load(f)
    issues = []
    for change in plan.get("resource_changes", []):
        after = change.get("change", {}).get("after", {})
        resource_type = change.get("type", "")
        address = change.get("address", "")
        if resource_type == "aws_s3_bucket":
            if not after.get("server_side_encryption_configuration"):
                issues.append({"resource": address, "issue": "S3 bucket without encryption", "severity": "HIGH"})
        if resource_type == "aws_security_group_rule":
            for cidr in after.get("cidr_blocks", []):
                if cidr == "0.0.0.0/0" and after.get("from_port", 0) <= 22 <= after.get("to_port", 0):
                    issues.append({"resource": address, "issue": "SSH open to 0.0.0.0/0", "severity": "CRITICAL"})
        if resource_type == "aws_iam_policy":
            policy_doc = after.get("policy", "{}")
            if isinstance(policy_doc, str):
                try:
                    doc = json.loads(policy_doc)
                    for stmt in doc.get("Statement", []):
                        if stmt.get("Action") == "*" and stmt.get("Effect") == "Allow":
                            issues.append({"resource": address, "issue": "IAM wildcard actions", "severity": "CRITICAL"})
                except json.JSONDecodeError:
                    pass
    return issues


def generate_report(checkov_findings, tfsec_findings, plan_issues):
    """Generate combined audit report."""
    all_findings = []
    for f in checkov_findings:
        f["source"] = "checkov"
        all_findings.append(f)
    for f in tfsec_findings:
        f["source"] = "tfsec"
        all_findings.append(f)
    for f in plan_issues:
        f["source"] = "plan_scan"
        all_findings.append(f)
    severity_order = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2, "LOW": 3}
    all_findings.sort(key=lambda x: severity_order.get(x.get("severity", "LOW"), 4))
    return {
        "audit_date": datetime.utcnow().isoformat(),
        "total_findings": len(all_findings),
        "critical": sum(1 for f in all_findings if f.get("severity") == "CRITICAL"),
        "high": sum(1 for f in all_findings if f.get("severity") == "HIGH"),
        "findings": all_findings,
    }


def main():
    parser = argparse.ArgumentParser(description="Terraform Security Audit Agent")
    parser.add_argument("--terraform-dir", help="Directory with Terraform code")
    parser.add_argument("--plan-json", help="Terraform plan JSON file")
    parser.add_argument("--output", default="terraform_audit.json")
    parser.add_argument("--tool", choices=["checkov", "tfsec", "both", "plan_only"], default="both")
    args = parser.parse_args()

    checkov_findings = []
    tfsec_findings = []
    plan_issues = []

    if args.terraform_dir:
        if args.tool in ("checkov", "both"):
            print("[+] Running Checkov...")
            raw = run_checkov(args.terraform_dir)
            checkov_findings = parse_checkov_results(raw)
            print(f"    Found {len(checkov_findings)} issues")
        if args.tool in ("tfsec", "both"):
            print("[+] Running tfsec...")
            raw = run_tfsec(args.terraform_dir)
            tfsec_findings = parse_tfsec_results(raw)
            print(f"    Found {len(tfsec_findings)} issues")

    if args.plan_json:
        print("[+] Scanning Terraform plan...")
        plan_issues = scan_tf_plan_for_issues(args.plan_json)
        print(f"    Found {len(plan_issues)} issues")

    report = generate_report(checkov_findings, tfsec_findings, plan_issues)
    with open(args.output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"[+] {report['critical']} critical, {report['high']} high out of {report['total_findings']} total")
    print(f"[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Adversary Infrastructure Tracking Agent - Tracks threat actor infrastructure using passive DNS and certificate transparency."""

import json
import logging
import argparse
from datetime import datetime
from collections import defaultdict

import requests

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


def query_crtsh(domain):
    """Query crt.sh certificate transparency for domain certificates."""
    resp = requests.get(f"https://crt.sh/?q=%.{domain}&output=json", timeout=30)
    resp.raise_for_status()
    certs = resp.json()
    logger.info("crt.sh: %d certificates for %s", len(certs), domain)
    return certs


def query_urlhaus(ioc, ioc_type="host"):
    """Query URLhaus for malicious URL hosting information."""
    resp = requests.post("https://urlhaus-api.abuse.ch/v1/host/", data={ioc_type: ioc}, timeout=15)
    resp.raise_for_status()
    return resp.json()


def query_threatfox(ioc):
    """Query ThreatFox for IOC intelligence."""
    resp = requests.post("https://threatfox-api.abuse.ch/api/v1/", json={"query": "search_ioc", "search_term": ioc}, timeout=15)
    resp.raise_for_status()
    return resp.json()


def pivot_on_certificate(cert_data):
    """Pivot on certificate data to find related infrastructure."""
    related_domains = set()
    issuers = defaultdict(list)
    for cert in cert_data:
        name_value = cert.get("name_value", "")
        for domain in name_value.split("\n"):
            domain = domain.strip().lstrip("*.")
            if domain:
                related_domains.add(domain)
        issuer = cert.get("issuer_name", "")
        issuers[issuer].append(cert.get("serial_number", ""))
    return {"related_domains": sorted(related_domains), "issuers": {k: len(v) for k, v in issuers.items()}}


def build_infrastructure_map(seed_iocs, ioc_types):
    """Build infrastructure map from seed IOCs."""
    infra_map = {"nodes": [], "edges": [], "iocs": {}}
    for ioc, itype in zip(seed_iocs, ioc_types):
        node = {"ioc": ioc, "type": itype, "sources": []}
        if itype == "domain":
            try:
                certs = query_crtsh(ioc)
                pivot = pivot_on_certificate(certs)
                node["ct_domains"] = pivot["related_domains"][:20]
                node["sources"].append("crt.sh")
                for related in pivot["related_domains"][:5]:
                    infra_map["edges"].append({"from": ioc, "to": related, "relation": "shared_certificate"})
            except requests.RequestException as e:
                node["ct_error"] = str(e)
        try:
            urlhaus = query_urlhaus(ioc, "host" if itype == "domain" else "host")
            if urlhaus.get("query_status") == "ok" and urlhaus.get("urls"):
                node["urlhaus_urls"] = len(urlhaus.get("urls", []))
                node["sources"].append("urlhaus")
        except requests.RequestException:
            pass
        try:
            tf = query_threatfox(ioc)
            if tf.get("query_status") == "ok" and tf.get("data"):
                node["threatfox_hits"] = len(tf["data"])
                node["sources"].append("threatfox")
        except requests.RequestException:
            pass
        infra_map["nodes"].append(node)
        infra_map["iocs"][ioc] = node
    return infra_map


def generate_report(infra_map, seed_iocs):
    """Generate infrastructure tracking report."""
    report = {
        "timestamp": datetime.utcnow().isoformat(),
        "seed_iocs": seed_iocs,
        "nodes_discovered": len(infra_map["nodes"]),
        "edges_discovered": len(infra_map["edges"]),
        "infrastructure_map": infra_map,
    }
    print(f"INFRA REPORT: {len(infra_map['nodes'])} nodes, {len(infra_map['edges'])} edges")
    return report


def main():
    parser = argparse.ArgumentParser(description="Adversary Infrastructure Tracking Agent")
    parser.add_argument("--iocs", nargs="+", required=True, help="Seed IOCs (domains/IPs)")
    parser.add_argument("--types", nargs="+", required=True, help="IOC types (domain/ip)")
    parser.add_argument("--output", default="infra_tracking_report.json")
    args = parser.parse_args()

    infra_map = build_infrastructure_map(args.iocs, args.types)
    report = generate_report(infra_map, args.iocs)
    with open(args.output, "w") as f:
        json.dump(report, f, indent=2)
    logger.info("Report saved to %s", args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# For authorized red-team engagements and defensive research only.
# Deploying C2 infrastructure outside an agreed scope is illegal.
"""C2 redirector configuration generator and validator.

Generates a filtering nginx reverse-proxy redirector config from a set of C2
URI patterns + implant User-Agent (mirroring what cs2modrewrite/cs2nginx do),
and validates a live redirector: matching requests should proxy to the backend
while non-matching requests must be diverted (302) to a decoy.
"""

import argparse
import json
import sys
from datetime import datetime, timezone

NGINX_TEMPLATE = """server {{
    listen 443 ssl;
    server_name {domain};

    ssl_certificate     /etc/letsencrypt/live/{domain}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/{domain}/privkey.pem;

    location ~ {uri_regex} {{
        if ($http_user_agent != "{user_agent}") {{
            return 302 {decoy};
        }}
        proxy_pass {teamserver};
        proxy_ssl_verify off;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $remote_addr;
    }}

    location / {{
        return 302 {decoy};
    }}
}}
"""


def build_uri_regex(uris):
    """Turn a list of C2 URIs into an nginx location regex."""
    cleaned = [u.strip().lstrip("/") for u in uris if u.strip()]
    if not cleaned:
        sys.exit("[!] No C2 URIs provided")
    return "^/(" + "|".join(cleaned) + ")"


def generate_config(args):
    """Render the nginx redirector config."""
    cfg = NGINX_TEMPLATE.format(
        domain=args.domain,
        uri_regex=build_uri_regex(args.uri),
        user_agent=args.user_agent,
        teamserver=args.teamserver,
        decoy=args.decoy,
    )
    if args.output:
        with open(args.output, "w") as f:
            f.write(cfg)
        print(f"[+] nginx redirector config written to {args.output}")
    else:
        print(cfg)


def validate_redirector(args):
    """Probe a live redirector: decoy on miss, proxy on match."""
    try:
        import requests
        from urllib3.exceptions import InsecureRequestWarning
        requests.packages.urllib3.disable_warnings(InsecureRequestWarning)
    except ImportError:
        sys.exit("[!] pip install requests for --validate")

    base = f"https://{args.domain}"
    report = {"checked": datetime.now(timezone.utc).isoformat(), "results": []}

    # 1. Non-matching request should be diverted (302/redirect to decoy)
    r1 = requests.get(base + "/", allow_redirects=False, verify=False, timeout=15)
    diverted = r1.status_code in (301, 302) and args.decoy.rstrip("/") in \
        r1.headers.get("Location", "")
    report["results"].append({"check": "non_c2_diverted", "status": r1.status_code,
                              "location": r1.headers.get("Location"), "pass": diverted})

    # 2. Matching request (correct UA + C2 URI) should be proxied (not 302-decoy)
    c2_path = "/" + args.uri[0].strip().lstrip("/").split("|")[0]
    r2 = requests.get(base + c2_path, headers={"User-Agent": args.user_agent},
                      allow_redirects=False, verify=False, timeout=15)
    proxied = not (r2.status_code in (301, 302) and
                   args.decoy.rstrip("/") in r2.headers.get("Location", ""))
    report["results"].append({"check": "c2_proxied", "path": c2_path,
                              "status": r2.status_code, "pass": proxied})

    print(json.dumps(report, indent=2))
    return all(x["pass"] for x in report["results"])


def main():
    p = argparse.ArgumentParser(description="C2 redirector config generator/validator")
    sub = p.add_subparsers(dest="cmd", required=True)

    g = sub.add_parser("generate", help="Generate an nginx redirector config")
    g.add_argument("--domain", required=True, help="Public redirector domain")
    g.add_argument("--teamserver", required=True, help="https://team-server backend URL")
    g.add_argument("--decoy", required=True, help="Decoy site URL for non-C2 traffic")
    g.add_argument("--uri", required=True, nargs="+", help="C2 URI patterns (no leading /)")
    g.add_argument("--user-agent", required=True, help="Implant User-Agent string")
    g.add_argument("--output", help="Write config to file")

    v = sub.add_parser("validate", help="Probe a live redirector")
    v.add_argument("--domain", required=True, help="Public redirector domain")
    v.add_argument("--decoy", required=True, help="Expected decoy URL")
    v.add_argument("--uri", required=True, nargs="+", help="C2 URI patterns")
    v.add_argument("--user-agent", required=True, help="Implant User-Agent string")

    args = p.parse_args()
    if args.cmd == "generate":
        generate_config(args)
    elif args.cmd == "validate":
        ok = validate_redirector(args)
        sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Splunk SPL Detection Rule Builder Agent - Generates and validates Splunk detection rules."""

import json
import logging
import os
import argparse
from datetime import datetime

import requests

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

DETECTION_TEMPLATES = {
    "brute_force": {
        "spl": 'index=main sourcetype=WinEventLog:Security EventCode=4625 | stats count by src_ip, user | where count > {threshold}',
        "description": "Detect brute force login attempts",
        "mitre": "T1110",
        "severity": "high",
    },
    "lateral_movement_rdp": {
        "spl": 'index=main sourcetype=WinEventLog:Security EventCode=4624 Logon_Type=10 | stats count by src_ip, dest, user | where count > 1',
        "description": "Detect RDP lateral movement",
        "mitre": "T1021.001",
        "severity": "high",
    },
    "powershell_encoded": {
        "spl": 'index=main sourcetype=WinEventLog:Security EventCode=4104 ScriptBlockText="*-EncodedCommand*" OR ScriptBlockText="*FromBase64String*" | table _time, ComputerName, ScriptBlockText',
        "description": "Detect encoded PowerShell execution",
        "mitre": "T1059.001",
        "severity": "critical",
    },
    "suspicious_process": {
        "spl": 'index=main sourcetype=sysmon EventCode=1 (ParentImage="*\\\\cmd.exe" OR ParentImage="*\\\\powershell.exe") (Image="*\\\\whoami.exe" OR Image="*\\\\net.exe" OR Image="*\\\\nltest.exe") | table _time, Computer, User, ParentImage, Image, CommandLine',
        "description": "Detect suspicious child process spawning",
        "mitre": "T1059.003",
        "severity": "high",
    },
    "scheduled_task_creation": {
        "spl": 'index=main sourcetype=WinEventLog:Security EventCode=4698 | table _time, SubjectUserName, TaskName, TaskContent',
        "description": "Detect new scheduled task creation",
        "mitre": "T1053.005",
        "severity": "medium",
    },
    "credential_dumping": {
        "spl": 'index=main sourcetype=sysmon EventCode=10 TargetImage="*\\\\lsass.exe" GrantedAccess IN ("0x1010", "0x1038", "0x1fffff") | table _time, SourceImage, TargetImage, GrantedAccess',
        "description": "Detect LSASS memory access (credential dumping)",
        "mitre": "T1003.001",
        "severity": "critical",
    },
    "data_exfiltration": {
        "spl": 'index=main sourcetype=proxy | stats sum(bytes_out) as total_bytes by src_ip, dest | where total_bytes > {threshold_bytes} | eval MB=round(total_bytes/1024/1024,2)',
        "description": "Detect large data transfers (exfiltration)",
        "mitre": "T1048",
        "severity": "high",
    },
}


def generate_spl_rule(template_name, params=None):
    """Generate an SPL detection rule from template."""
    if template_name not in DETECTION_TEMPLATES:
        return {"error": f"Unknown template: {template_name}"}
    template = DETECTION_TEMPLATES[template_name]
    spl = template["spl"]
    if params:
        for key, value in params.items():
            spl = spl.replace(f"{{{key}}}", str(value))
    return {
        "name": template_name,
        "spl": spl,
        "description": template["description"],
        "mitre_technique": template["mitre"],
        "severity": template["severity"],
    }


def deploy_saved_search(splunk_url, token, rule_name, spl, severity="high"):
    """Deploy a saved search to Splunk via REST API."""
    headers = {"Authorization": f"Bearer {token}"}
    data = {
        "name": f"Detection - {rule_name}",
        "search": spl,
        "is_scheduled": 1,
        "cron_schedule": "*/5 * * * *",
        "dispatch.earliest_time": "-5m",
        "dispatch.latest_time": "now",
        "alert.severity": {"info": 1, "low": 2, "medium": 3, "high": 4, "critical": 5}.get(severity, 4),
        "alert_type": "number of events",
        "alert_comparator": "greater than",
        "alert_threshold": "0",
        "actions": "email",
    }
    try:
        resp = requests.post(f"{splunk_url}/servicesNS/admin/search/saved/searches", headers=headers, data=data, verify=not os.environ.get("SKIP_TLS_VERIFY", "").lower() == "true", timeout=30)  # Set SKIP_TLS_VERIFY=true for self-signed certs in lab environments
        return {"status": resp.status_code, "deployed": resp.status_code in (200, 201)}
    except requests.RequestException as e:
        return {"error": str(e)}


def generate_report(rules, deployment_results=None):
    """Generate detection rule report."""
    report = {
        "timestamp": datetime.utcnow().isoformat(),
        "rules_generated": len(rules),
        "rules": rules,
        "deployment_results": deployment_results or [],
    }
    print(f"SPL REPORT: {len(rules)} detection rules generated")
    return report


def main():
    parser = argparse.ArgumentParser(description="Splunk SPL Detection Rule Builder Agent")
    parser.add_argument("--templates", nargs="*", choices=list(DETECTION_TEMPLATES.keys()), default=list(DETECTION_TEMPLATES.keys()))
    parser.add_argument("--threshold", type=int, default=10)
    parser.add_argument("--threshold-bytes", type=int, default=104857600)
    parser.add_argument("--splunk-url", help="Splunk URL for deployment")
    parser.add_argument("--splunk-token", help="Splunk auth token")
    parser.add_argument("--output", default="splunk_rules.json")
    args = parser.parse_args()

    rules = []
    for template in args.templates:
        rule = generate_spl_rule(template, {"threshold": args.threshold, "threshold_bytes": args.threshold_bytes})
        rules.append(rule)

    deployments = []
    if args.splunk_url and args.splunk_token:
        for rule in rules:
            result = deploy_saved_search(args.splunk_url, args.splunk_token, rule["name"], rule["spl"], rule["severity"])
            deployments.append({"rule": rule["name"], "result": result})

    report = generate_report(rules, deployments)
    with open(args.output, "w") as f:
        json.dump(report, f, indent=2)
    logger.info("Report saved to %s", args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Agent for building and converting Sigma detection rules."""

import json
import argparse
from datetime import datetime
from pathlib import Path

from sigma.rule import SigmaRule
from sigma.backends.splunk import SplunkBackend
from sigma.pipelines.splunk import splunk_windows_pipeline


def load_sigma_rule(rule_path):
    """Load a Sigma rule from a YAML file."""
    with open(rule_path) as f:
        return SigmaRule.from_yaml(f.read())


def load_sigma_directory(directory):
    """Load all Sigma rules from a directory."""
    rules = []
    for path in Path(directory).rglob("*.yml"):
        try:
            rule = load_sigma_rule(str(path))
            rules.append({"path": str(path), "rule": rule})
        except Exception as e:
            print(f"  Warning: Failed to parse {path}: {e}")
    return rules


def convert_to_splunk(rule):
    """Convert a Sigma rule to Splunk SPL query."""
    pipeline = splunk_windows_pipeline()
    backend = SplunkBackend(pipeline)
    queries = backend.convert_rule(rule)
    return queries


def convert_to_splunk_savedsearch(rule):
    """Convert a Sigma rule to Splunk saved search format."""
    pipeline = splunk_windows_pipeline()
    backend = SplunkBackend(pipeline)
    return backend.convert_rule(rule, output_format="savedsearches")


def validate_sigma_rule(rule_path):
    """Validate a Sigma rule for syntax and best practices."""
    issues = []
    try:
        rule = load_sigma_rule(rule_path)
        if not rule.title:
            issues.append("Missing title")
        if not rule.id:
            issues.append("Missing rule ID")
        if not rule.level:
            issues.append("Missing severity level")
        if not rule.tags:
            issues.append("Missing ATT&CK tags")
        if not rule.description:
            issues.append("Missing description")
        if not rule.logsource:
            issues.append("Missing logsource definition")
        return {"valid": len(issues) == 0, "issues": issues, "title": str(rule.title)}
    except Exception as e:
        return {"valid": False, "issues": [str(e)]}


def extract_attack_techniques(rules):
    """Extract MITRE ATT&CK technique IDs from Sigma rules."""
    techniques = {}
    for entry in rules:
        rule = entry["rule"]
        for tag in rule.tags:
            tag_str = str(tag)
            if tag_str.startswith("attack.t"):
                technique_id = tag_str.replace("attack.", "").upper()
                if technique_id not in techniques:
                    techniques[technique_id] = []
                techniques[technique_id].append(str(rule.title))
    return techniques


def generate_attack_navigator_layer(techniques, layer_name="Sigma Detection Coverage"):
    """Generate a MITRE ATT&CK Navigator layer JSON from extracted techniques."""
    layer = {
        "name": layer_name,
        "versions": {"attack": "14", "navigator": "4.9", "layer": "4.5"},
        "domain": "enterprise-attack",
        "techniques": [],
    }
    for tid, rule_names in techniques.items():
        layer["techniques"].append({
            "techniqueID": tid,
            "color": "#31a354",
            "score": len(rule_names),
            "comment": "; ".join(rule_names[:3]),
        })
    return layer


def batch_convert(directory, backend_name="splunk"):
    """Batch convert all Sigma rules in a directory to target backend."""
    rules = load_sigma_directory(directory)
    converted = []
    for entry in rules:
        try:
            if backend_name == "splunk":
                queries = convert_to_splunk(entry["rule"])
                converted.append({
                    "file": entry["path"],
                    "title": str(entry["rule"].title),
                    "level": str(entry["rule"].level),
                    "queries": [str(q) for q in queries],
                })
        except Exception as e:
            converted.append({"file": entry["path"], "error": str(e)})
    return converted


def main():
    parser = argparse.ArgumentParser(description="Sigma Detection Rule Builder Agent")
    parser.add_argument("--rule", help="Path to a single Sigma rule YAML file")
    parser.add_argument("--directory", help="Directory of Sigma rules")
    parser.add_argument("--backend", choices=["splunk"], default="splunk")
    parser.add_argument("--output", default="sigma_output.json")
    parser.add_argument("--action", choices=[
        "validate", "convert", "batch_convert", "coverage", "full_pipeline"
    ], default="full_pipeline")
    args = parser.parse_args()

    report = {"generated_at": datetime.utcnow().isoformat()}

    if args.action == "validate" and args.rule:
        result = validate_sigma_rule(args.rule)
        print(f"[+] Validation: {'PASS' if result['valid'] else 'FAIL'}")
        if result["issues"]:
            for issue in result["issues"]:
                print(f"    - {issue}")
        report["validation"] = result

    if args.action == "convert" and args.rule:
        rule = load_sigma_rule(args.rule)
        queries = convert_to_splunk(rule)
        print(f"[+] Converted '{rule.title}' to Splunk SPL:")
        for q in queries:
            print(f"    {q}")
        report["conversion"] = {"title": str(rule.title), "queries": [str(q) for q in queries]}

    if args.action in ("batch_convert", "full_pipeline") and args.directory:
        converted = batch_convert(args.directory, args.backend)
        success = sum(1 for c in converted if "queries" in c)
        print(f"[+] Batch converted {success}/{len(converted)} rules to {args.backend}")
        report["batch_conversion"] = converted

    if args.action in ("coverage", "full_pipeline") and args.directory:
        rules = load_sigma_directory(args.directory)
        techniques = extract_attack_techniques(rules)
        layer = generate_attack_navigator_layer(techniques)
        layer_path = args.output.replace(".json", "_layer.json")
        with open(layer_path, "w") as f:
            json.dump(layer, f, indent=2)
        print(f"[+] ATT&CK coverage: {len(techniques)} techniques from {len(rules)} rules")
        print(f"[+] Navigator layer saved to {layer_path}")
        report["coverage"] = {"techniques": len(techniques), "rules": len(rules)}

    with open(args.output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"[+] Output saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""DevSecOps Pipeline Builder Agent - Generates GitLab CI security scanning pipeline configurations."""

import json
import logging
import argparse
from datetime import datetime

import requests

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

SECURITY_STAGES = {
    "sast": {
        "template": "Security/SAST.gitlab-ci.yml",
        "description": "Static Application Security Testing",
        "tools": ["semgrep", "bandit", "eslint-security"],
    },
    "dast": {
        "template": "Security/DAST.gitlab-ci.yml",
        "description": "Dynamic Application Security Testing",
        "tools": ["zap"],
    },
    "dependency_scanning": {
        "template": "Security/Dependency-Scanning.gitlab-ci.yml",
        "description": "Dependency vulnerability scanning",
        "tools": ["gemnasium", "retire.js"],
    },
    "container_scanning": {
        "template": "Security/Container-Scanning.gitlab-ci.yml",
        "description": "Container image vulnerability scanning",
        "tools": ["trivy", "grype"],
    },
    "secret_detection": {
        "template": "Security/Secret-Detection.gitlab-ci.yml",
        "description": "Secret and credential detection",
        "tools": ["gitleaks"],
    },
    "license_scanning": {
        "template": "Jobs/License-Scanning.gitlab-ci.yml",
        "description": "License compliance scanning",
        "tools": ["license-finder"],
    },
    "iac_scanning": {
        "template": "Security/IaC-Scanning.gitlab-ci.yml",
        "description": "Infrastructure as Code scanning",
        "tools": ["kics"],
    },
}


def generate_gitlab_ci(stages, project_type="python", registry="$CI_REGISTRY"):
    """Generate .gitlab-ci.yml with security scanning stages."""
    ci_config = {
        "stages": ["build", "test", "security", "deploy"],
        "include": [],
        "variables": {
            "SECURE_LOG_LEVEL": "info",
            "SAST_EXCLUDED_ANALYZERS": "",
        },
    }
    for stage_name in stages:
        stage = SECURITY_STAGES.get(stage_name)
        if stage:
            ci_config["include"].append({"template": stage["template"]})

    if "container_scanning" in stages:
        ci_config["variables"]["CS_IMAGE"] = f"{registry}/$CI_PROJECT_PATH:$CI_COMMIT_SHA"

    if project_type == "python":
        ci_config["variables"]["SAST_DEFAULT_ANALYZERS"] = "semgrep,bandit"
    elif project_type == "javascript":
        ci_config["variables"]["SAST_DEFAULT_ANALYZERS"] = "semgrep,eslint"

    return ci_config


def validate_pipeline(gitlab_url, token, project_id, ci_content):
    """Validate CI configuration via GitLab API."""
    headers = {"PRIVATE-TOKEN": token, "Content-Type": "application/json"}
    data = {"content": json.dumps(ci_content)}
    try:
        resp = requests.post(f"{gitlab_url}/api/v4/projects/{project_id}/ci/lint", headers=headers, json=data, timeout=15)
        return resp.json()
    except requests.RequestException as e:
        return {"error": str(e)}


def assess_pipeline_coverage(stages):
    """Assess security coverage of the pipeline."""
    all_stages = set(SECURITY_STAGES.keys())
    covered = set(stages) & all_stages
    missing = all_stages - covered
    coverage = len(covered) / len(all_stages) * 100
    return {
        "coverage_percent": round(coverage, 1),
        "covered_stages": list(covered),
        "missing_stages": list(missing),
        "recommendation": "Add " + ", ".join(missing) if missing else "Full coverage",
    }


def generate_report(ci_config, coverage, stages):
    """Generate DevSecOps pipeline report."""
    report = {
        "timestamp": datetime.utcnow().isoformat(),
        "stages_configured": stages,
        "security_coverage": coverage,
        "gitlab_ci_config": ci_config,
    }
    print(f"DEVSECOPS REPORT: {len(stages)} stages, {coverage['coverage_percent']}% coverage")
    return report


def main():
    parser = argparse.ArgumentParser(description="DevSecOps Pipeline Builder Agent")
    parser.add_argument("--stages", nargs="*", choices=list(SECURITY_STAGES.keys()), default=list(SECURITY_STAGES.keys()))
    parser.add_argument("--project-type", choices=["python", "javascript", "java", "go"], default="python")
    parser.add_argument("--gitlab-url", help="GitLab URL for validation")
    parser.add_argument("--token", help="GitLab private token")
    parser.add_argument("--project-id", help="GitLab project ID")
    parser.add_argument("--output", default="devsecops_report.json")
    args = parser.parse_args()

    ci_config = generate_gitlab_ci(args.stages, args.project_type)
    coverage = assess_pipeline_coverage(args.stages)
    report = generate_report(ci_config, coverage, args.stages)
    with open(args.output, "w") as f:
        json.dump(report, f, indent=2)
    logger.info("Report saved to %s", args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
GitLab DevSecOps Pipeline Security Report Generator

Queries GitLab API to aggregate security scanning results
across projects and generate compliance reports.
"""

import json
import os
import sys
import urllib.request
import urllib.error
from datetime import datetime
from collections import defaultdict


def gitlab_api_get(url: str, token: str) -> list | dict:
    headers = {"PRIVATE-TOKEN": token, "Content-Type": "application/json"}
    results = []
    page = 1
    while True:
        sep = "&" if "?" in url else "?"
        paginated = f"{url}{sep}per_page=100&page={page}"
        req = urllib.request.Request(paginated, headers=headers)
        try:
            with urllib.request.urlopen(req) as resp:
                data = json.loads(resp.read().decode())
                if isinstance(data, list):
                    if not data:
                        break
                    results.extend(data)
                    page += 1
                else:
                    return data
        except urllib.error.HTTPError as e:
            print(f"HTTP {e.code}: {e.read().decode()}")
            break
    return results


def get_group_projects(base_url: str, token: str, group_id: str) -> list:
    url = f"{base_url}/api/v4/groups/{group_id}/projects?include_subgroups=true"
    return gitlab_api_get(url, token)


def get_project_vulnerabilities(base_url: str, token: str, project_id: int) -> list:
    url = f"{base_url}/api/v4/projects/{project_id}/vulnerabilities?state=detected"
    return gitlab_api_get(url, token)


def get_pipeline_jobs(base_url: str, token: str, project_id: int, pipeline_id: int) -> list:
    url = f"{base_url}/api/v4/projects/{project_id}/pipelines/{pipeline_id}/jobs"
    return gitlab_api_get(url, token)


def check_security_scanners(jobs: list) -> dict:
    scanner_names = {
        "sast": False,
        "secret_detection": False,
        "dependency_scanning": False,
        "container_scanning": False,
        "dast": False,
        "license_scanning": False,
    }
    for job in jobs:
        name = job.get("name", "").lower()
        for scanner in scanner_names:
            if scanner.replace("_", "-") in name or scanner in name:
                scanner_names[scanner] = True
    return scanner_names


def generate_report(base_url: str, token: str, group_id: str) -> dict:
    projects = get_group_projects(base_url, token, group_id)
    report = {
        "gitlab_instance": base_url,
        "group_id": group_id,
        "generated_at": datetime.utcnow().isoformat() + "Z",
        "total_projects": len(projects),
        "scanner_coverage": defaultdict(int),
        "severity_totals": defaultdict(int),
        "project_details": [],
    }

    for project in projects:
        pid = project["id"]
        name = project["path_with_namespace"]

        vulns = get_project_vulnerabilities(base_url, token, pid)
        severity_counts = defaultdict(int)
        scanner_counts = defaultdict(int)
        for v in vulns:
            severity_counts[v.get("severity", "unknown")] += 1
            scanner_counts[v.get("scanner", {}).get("name", "unknown")] += 1
            report["severity_totals"][v.get("severity", "unknown")] += 1

        pipelines = gitlab_api_get(
            f"{base_url}/api/v4/projects/{pid}/pipelines?per_page=1&status=success", token
        )
        scanners_enabled = {}
        if pipelines and isinstance(pipelines, list):
            jobs = get_pipeline_jobs(base_url, token, pid, pipelines[0]["id"])
            scanners_enabled = check_security_scanners(jobs)
            for scanner, enabled in scanners_enabled.items():
                if enabled:
                    report["scanner_coverage"][scanner] += 1

        report["project_details"].append({
            "project": name,
            "open_vulnerabilities": len(vulns),
            "by_severity": dict(severity_counts),
            "by_scanner": dict(scanner_counts),
            "scanners_enabled": scanners_enabled,
        })

    report["scanner_coverage"] = dict(report["scanner_coverage"])
    report["severity_totals"] = dict(report["severity_totals"])
    return report


def print_report(report: dict) -> None:
    print(f"\n{'='*65}")
    print(f"GitLab DevSecOps Security Report")
    print(f"Instance: {report['gitlab_instance']}")
    print(f"Generated: {report['generated_at']}")
    print(f"{'='*65}")
    print(f"\nTotal Projects: {report['total_projects']}")

    print(f"\nScanner Coverage:")
    for scanner, count in sorted(report["scanner_coverage"].items()):
        pct = count / report["total_projects"] * 100 if report["total_projects"] > 0 else 0
        print(f"  {scanner:25s}: {count:3d}/{report['total_projects']} ({pct:.0f}%)")

    print(f"\nVulnerability Summary:")
    for sev in ["critical", "high", "medium", "low", "info", "unknown"]:
        count = report["severity_totals"].get(sev, 0)
        if count > 0:
            print(f"  {sev.upper():12s}: {count}")

    total = sum(report["severity_totals"].values())
    print(f"  {'TOTAL':12s}: {total}")

    print(f"\nTop 10 Projects by Open Vulnerabilities:")
    sorted_projects = sorted(
        report["project_details"], key=lambda p: p["open_vulnerabilities"], reverse=True
    )
    for p in sorted_projects[:10]:
        print(f"  {p['project']:45s} | Vulns: {p['open_vulnerabilities']}")


def main():
    token = os.environ.get("GITLAB_TOKEN")
    base_url = os.environ.get("GITLAB_URL", "https://gitlab.com")
    group_id = os.environ.get("GITLAB_GROUP_ID")

    if not token:
        print("Error: GITLAB_TOKEN environment variable required")
        sys.exit(1)
    if not group_id:
        print("Error: GITLAB_GROUP_ID environment variable required")
        sys.exit(1)

    report = generate_report(base_url, token, group_id)
    print_report(report)

    output = f"gitlab_devsecops_report_{datetime.utcnow().strftime('%Y%m%d')}.json"
    with open(output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"\nReport saved to: {output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Azure AD Federation Configuration Auditor

Validates federation configuration between on-premises AD FS and Azure AD,
checks certificate health, and monitors federation authentication events.

Requirements:
    pip install msal requests cryptography
"""

import json
import sys
from datetime import datetime, timezone

try:
    import requests
    import msal
    from cryptography import x509
except ImportError:
    print("[ERROR] Required: pip install msal requests cryptography")
    sys.exit(1)


class FederationAuditor:
    """Audit Azure AD federation configuration and health."""

    def __init__(self, tenant_id, client_id, client_secret):
        self.tenant_id = tenant_id
        self.token = self._get_token(tenant_id, client_id, client_secret)

    def _get_token(self, tenant_id, client_id, client_secret):
        app = msal.ConfidentialClientApplication(
            client_id,
            authority=f"https://login.microsoftonline.com/{tenant_id}",
            client_credential=client_secret,
        )
        result = app.acquire_token_for_client(
            scopes=["https://graph.microsoft.com/.default"]
        )
        if "access_token" in result:
            return result["access_token"]
        raise Exception(f"Auth failed: {result.get('error_description')}")

    def _graph_get(self, endpoint):
        headers = {"Authorization": f"Bearer {self.token}"}
        resp = requests.get(
            f"https://graph.microsoft.com/v1.0{endpoint}",
            headers=headers,
        )
        resp.raise_for_status()
        return resp.json()

    def get_domains(self):
        """List all domains and their authentication type."""
        result = self._graph_get("/domains")
        domains = []
        for domain in result.get("value", []):
            domains.append({
                "id": domain["id"],
                "isVerified": domain.get("isVerified", False),
                "authenticationType": domain.get("authenticationType", "Unknown"),
                "isDefault": domain.get("isDefault", False),
                "isRoot": domain.get("isRoot", False),
            })
        return domains

    def get_federation_config(self, domain_id):
        """Get federation configuration for a specific domain."""
        try:
            result = self._graph_get(
                f"/domains/{domain_id}/federationConfiguration"
            )
            configs = result.get("value", [])
            return configs[0] if configs else None
        except requests.HTTPError as e:
            if e.response.status_code == 404:
                return None
            raise

    def validate_adfs_metadata(self, metadata_url):
        """Fetch and validate AD FS federation metadata endpoint."""
        try:
            resp = requests.get(metadata_url, timeout=15)
            resp.raise_for_status()

            from lxml import etree
            root = etree.fromstring(resp.content)
            ns = {"md": "urn:oasis:names:tc:SAML:2.0:metadata"}

            entity_id = root.get("entityID")
            certs = root.findall(
                ".//md:IDPSSODescriptor/md:KeyDescriptor/ds:KeyInfo"
                "/ds:X509Data/ds:X509Certificate",
                {**ns, "ds": "http://www.w3.org/2000/09/xmldsig#"},
            )

            return {
                "reachable": True,
                "entity_id": entity_id,
                "certificate_count": len(certs),
                "metadata_size": len(resp.content),
            }
        except requests.RequestException as e:
            return {"reachable": False, "error": str(e)}
        except Exception as e:
            return {"reachable": True, "parse_error": str(e)}

    def check_certificate_expiry(self, cert_base64):
        """Check federation signing certificate expiration."""
        try:
            import base64
            cert_der = base64.b64decode(cert_base64)
            cert = x509.load_der_x509_certificate(cert_der)
            now = datetime.now(timezone.utc)
            days_left = (cert.not_valid_after_utc - now).days

            return {
                "subject": cert.subject.rfc4514_string(),
                "not_after": cert.not_valid_after_utc.isoformat(),
                "days_until_expiry": days_left,
                "is_expired": days_left < 0,
                "needs_renewal": days_left < 30,
            }
        except Exception as e:
            return {"error": str(e)}

    def get_signin_logs(self, federated_domain, top=50):
        """Get recent sign-in logs for federated users."""
        try:
            result = self._graph_get(
                f"/auditLogs/signIns?"
                f"$filter=userPrincipalName endswith '{federated_domain}'"
                f"&$top={top}&$orderby=createdDateTime desc"
            )
            logs = []
            for log in result.get("value", []):
                logs.append({
                    "user": log.get("userPrincipalName"),
                    "createdDateTime": log.get("createdDateTime"),
                    "status": log.get("status", {}).get("errorCode", 0),
                    "statusDetail": log.get("status", {}).get("failureReason", "Success"),
                    "appDisplayName": log.get("appDisplayName"),
                    "authenticationProtocol": log.get("authenticationProtocol"),
                    "ipAddress": log.get("ipAddress"),
                })
            return logs
        except requests.HTTPError:
            return []

    def generate_federation_audit_report(self):
        """Generate comprehensive federation health report."""
        domains = self.get_domains()
        federated_domains = [d for d in domains if d["authenticationType"] == "Federated"]

        report = {
            "report_title": "Azure AD Federation Audit Report",
            "tenant_id": self.tenant_id,
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "total_domains": len(domains),
            "federated_domains": len(federated_domains),
            "domain_details": [],
            "findings": [],
        }

        for domain in federated_domains:
            domain_id = domain["id"]
            fed_config = self.get_federation_config(domain_id)

            domain_detail = {
                "domain": domain_id,
                "is_verified": domain["isVerified"],
                "federation_config": fed_config is not None,
            }

            if fed_config:
                issuer = fed_config.get("issuerUri", "")
                sign_in_url = fed_config.get("passiveSignInUri", "")
                domain_detail["issuer_uri"] = issuer
                domain_detail["sign_in_url"] = sign_in_url

                signing_cert = fed_config.get("signingCertificate", "")
                if signing_cert:
                    cert_health = self.check_certificate_expiry(signing_cert)
                    domain_detail["certificate_health"] = cert_health

                    if cert_health.get("is_expired"):
                        report["findings"].append({
                            "severity": "Critical",
                            "domain": domain_id,
                            "finding": "Federation signing certificate is EXPIRED",
                            "action": "Immediately rotate certificate in AD FS and update Azure AD",
                        })
                    elif cert_health.get("needs_renewal"):
                        report["findings"].append({
                            "severity": "High",
                            "domain": domain_id,
                            "finding": f"Federation certificate expires in {cert_health['days_until_expiry']} days",
                            "action": "Schedule certificate rotation before expiry",
                        })

            report["domain_details"].append(domain_detail)

        return report


if __name__ == "__main__":
    print("=" * 60)
    print("Azure AD Federation Configuration Auditor")
    print("=" * 60)
    print()
    print("Usage:")
    print("  auditor = FederationAuditor(tenant_id, client_id, secret)")
    print("  report = auditor.generate_federation_audit_report()")
    print("  print(json.dumps(report, indent=2))")
    print()
    print("Required Microsoft Graph permissions:")
    print("  - Domain.Read.All")
    print("  - AuditLog.Read.All")
    print("  - Directory.Read.All")

#!/usr/bin/env python3
"""Agent for identity governance and lifecycle management operations."""

import os
import json
import argparse
from datetime import datetime, timedelta

import requests


def get_graph_token(tenant_id, client_id, client_secret):
    """Authenticate to Microsoft Graph API via client credentials."""
    url = f"https://login.microsoftonline.com/{tenant_id}/oauth2/v2.0/token"
    resp = requests.post(url, data={
        "grant_type": "client_credentials",
        "client_id": client_id,
        "client_secret": client_secret,
        "scope": "https://graph.microsoft.com/.default",
    }, timeout=30)
    resp.raise_for_status()
    return resp.json()["access_token"]


def list_users(token, filter_query=None):
    """List users from Microsoft Entra ID with optional filter."""
    headers = {"Authorization": f"Bearer {token}"}
    url = "https://graph.microsoft.com/v1.0/users"
    params = {"$select": "id,displayName,userPrincipalName,accountEnabled,employeeId,"
              "department,jobTitle,createdDateTime,signInActivity",
              "$top": "999"}
    if filter_query:
        params["$filter"] = filter_query
    users = []
    while url:
        resp = requests.get(url, headers=headers, params=params, timeout=30)
        resp.raise_for_status()
        data = resp.json()
        users.extend(data.get("value", []))
        url = data.get("@odata.nextLink")
        params = {}
    return users


def detect_orphaned_accounts(token, days_inactive=90):
    """Find accounts with no sign-in activity for N days."""
    users = list_users(token)
    cutoff = datetime.utcnow() - timedelta(days=days_inactive)
    orphaned = []
    for u in users:
        if not u.get("accountEnabled"):
            continue
        sign_in = u.get("signInActivity", {})
        last_sign_in = sign_in.get("lastSignInDateTime")
        if not last_sign_in:
            orphaned.append({
                "user": u["userPrincipalName"],
                "department": u.get("department", ""),
                "reason": "No sign-in recorded",
                "risk": "HIGH",
            })
        else:
            last_dt = datetime.fromisoformat(last_sign_in.rstrip("Z"))
            if last_dt < cutoff:
                orphaned.append({
                    "user": u["userPrincipalName"],
                    "department": u.get("department", ""),
                    "last_sign_in": last_sign_in,
                    "days_inactive": (datetime.utcnow() - last_dt).days,
                    "risk": "MEDIUM",
                })
    return orphaned


def detect_stale_guests(token, days_inactive=60):
    """Find guest accounts with no recent activity."""
    guests = list_users(token, "userType eq 'Guest'")
    cutoff = datetime.utcnow() - timedelta(days=days_inactive)
    stale = []
    for g in guests:
        sign_in = g.get("signInActivity", {})
        last = sign_in.get("lastSignInDateTime")
        if not last or datetime.fromisoformat(last.rstrip("Z")) < cutoff:
            stale.append({
                "user": g["userPrincipalName"],
                "created": g.get("createdDateTime", ""),
                "last_sign_in": last,
            })
    return stale


def get_access_reviews(token):
    """List active access reviews from Entra ID Governance."""
    headers = {"Authorization": f"Bearer {token}"}
    url = "https://graph.microsoft.com/v1.0/identityGovernance/accessReviews/definitions"
    resp = requests.get(url, headers=headers, timeout=30)
    resp.raise_for_status()
    reviews = []
    for r in resp.json().get("value", []):
        reviews.append({
            "name": r["displayName"],
            "status": r["status"],
            "scope": r.get("scope", {}).get("query", ""),
            "created": r.get("createdDateTime"),
        })
    return reviews


def check_users_without_mfa(token):
    """Identify users without registered MFA methods."""
    headers = {"Authorization": f"Bearer {token}"}
    url = "https://graph.microsoft.com/v1.0/reports/authenticationMethods/userRegistrationDetails"
    resp = requests.get(url, headers=headers, params={"$top": "999"}, timeout=30)
    resp.raise_for_status()
    no_mfa = []
    for u in resp.json().get("value", []):
        if not u.get("isMfaRegistered"):
            no_mfa.append({
                "user": u["userPrincipalName"],
                "mfa_registered": False,
                "methods": u.get("methodsRegistered", []),
            })
    return no_mfa


def generate_lifecycle_report(token):
    """Generate comprehensive identity governance report."""
    report = {"generated_at": datetime.utcnow().isoformat(), "findings": {}}
    users = list_users(token)
    enabled = [u for u in users if u.get("accountEnabled")]
    disabled = [u for u in users if not u.get("accountEnabled")]
    report["summary"] = {
        "total_users": len(users),
        "enabled": len(enabled),
        "disabled": len(disabled),
    }
    report["findings"]["orphaned_accounts"] = detect_orphaned_accounts(token)
    report["findings"]["stale_guests"] = detect_stale_guests(token)
    report["findings"]["no_mfa"] = check_users_without_mfa(token)
    report["findings"]["access_reviews"] = get_access_reviews(token)
    return report


def main():
    parser = argparse.ArgumentParser(description="Identity Governance Lifecycle Agent")
    parser.add_argument("--tenant-id", default=os.getenv("AZURE_TENANT_ID"))
    parser.add_argument("--client-id", default=os.getenv("AZURE_CLIENT_ID"))
    parser.add_argument("--client-secret", default=os.getenv("AZURE_CLIENT_SECRET"))
    parser.add_argument("--output", default="iga_report.json")
    parser.add_argument("--action", choices=[
        "orphaned", "guests", "mfa", "reviews", "full_report"
    ], default="full_report")
    args = parser.parse_args()

    token = get_graph_token(args.tenant_id, args.client_id, args.client_secret)
    report = {"scan_date": datetime.utcnow().isoformat(), "findings": {}}

    if args.action in ("orphaned", "full_report"):
        results = detect_orphaned_accounts(token)
        report["findings"]["orphaned_accounts"] = results
        print(f"[+] Orphaned accounts: {len(results)}")

    if args.action in ("guests", "full_report"):
        results = detect_stale_guests(token)
        report["findings"]["stale_guests"] = results
        print(f"[+] Stale guest accounts: {len(results)}")

    if args.action in ("mfa", "full_report"):
        results = check_users_without_mfa(token)
        report["findings"]["no_mfa"] = results
        print(f"[+] Users without MFA: {len(results)}")

    if args.action in ("reviews", "full_report"):
        results = get_access_reviews(token)
        report["findings"]["access_reviews"] = results
        print(f"[+] Active access reviews: {len(results)}")

    with open(args.output, "w") as f:
        json.dump(report, f, indent=2, default=str)
    print(f"[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Agent for building and managing incident response playbooks."""

import os
