#!/usr/bin/env python3
"""
Threat Intelligence Platform Management Script

Manages a multi-component TIP deployment:
- Checks platform component health
- Configures feed ingestion across MISP and OpenCTI
- Runs enrichment pipelines via Cortex analyzers
- Generates platform metrics and dashboards

Requirements:
    pip install pymisp pycti requests

Usage:
    python process.py --check-health --misp-url URL --misp-key KEY --opencti-url URL --opencti-token TOKEN
    python process.py --configure-feeds --misp-url URL --misp-key KEY
    python process.py --platform-stats --misp-url URL --misp-key KEY --opencti-url URL --opencti-token TOKEN
"""

import argparse
import json
import sys
from datetime import datetime

import requests

try:
    from pymisp import PyMISP
except ImportError:
    PyMISP = None

try:
    from pycti import OpenCTIApiClient
except ImportError:
    OpenCTIApiClient = None


class TIPManager:
    """Manage Threat Intelligence Platform operations."""

    def __init__(self, misp_url="", misp_key="", opencti_url="", opencti_token="",
                 thehive_url="", thehive_key="", cortex_url="", cortex_key=""):
        self.misp = PyMISP(misp_url, misp_key, ssl=False) if PyMISP and misp_url else None
        self.opencti = (
            OpenCTIApiClient(opencti_url, opencti_token)
            if OpenCTIApiClient and opencti_url else None
        )
        self.thehive_url = thehive_url
        self.thehive_key = thehive_key
        self.cortex_url = cortex_url
        self.cortex_key = cortex_key

    def check_health(self) -> dict:
        """Check health of all platform components."""
        health = {}

        if self.misp:
            try:
                version = self.misp.misp_instance_version
                health["misp"] = {"status": "healthy", "version": str(version)}
            except Exception as e:
                health["misp"] = {"status": "unhealthy", "error": str(e)}

        if self.opencti:
            try:
                about = self.opencti.health.check()
                health["opencti"] = {"status": "healthy"}
            except Exception as e:
                health["opencti"] = {"status": "unhealthy", "error": str(e)}

        if self.thehive_url:
            try:
                resp = requests.get(
                    f"{self.thehive_url}/api/status",
                    headers={"Authorization": f"Bearer {self.thehive_key}"},
                    timeout=10,
                )
                health["thehive"] = {
                    "status": "healthy" if resp.status_code == 200 else "unhealthy"
                }
            except Exception as e:
                health["thehive"] = {"status": "unreachable", "error": str(e)}

        if self.cortex_url:
            try:
                resp = requests.get(
                    f"{self.cortex_url}/api/status",
                    headers={"Authorization": f"Bearer {self.cortex_key}"},
                    timeout=10,
                )
                health["cortex"] = {
                    "status": "healthy" if resp.status_code == 200 else "unhealthy"
                }
            except Exception as e:
                health["cortex"] = {"status": "unreachable", "error": str(e)}

        return health

    def configure_feeds(self) -> dict:
        """Configure default OSINT feeds in MISP."""
        if not self.misp:
            return {"error": "MISP not configured"}

        feeds = self.misp.feeds()
        enabled = []
        for feed in feeds:
            feed_info = feed.get("Feed", {})
            if not feed_info.get("enabled"):
                try:
                    self.misp.enable_feed(feed_info["id"])
                    enabled.append(feed_info["name"])
                except Exception:
                    pass

        return {"enabled_feeds": enabled, "total_feeds": len(feeds)}

    def get_platform_stats(self) -> dict:
        """Collect statistics from all platform components."""
        stats = {"timestamp": datetime.utcnow().isoformat()}

        if self.misp:
            try:
                server_stats = self.misp.get_server_statistics()
                feeds = self.misp.feeds()
                stats["misp"] = {
                    "events": server_stats.get("event_count", 0),
                    "attributes": server_stats.get("attribute_count", 0),
                    "active_feeds": len([
                        f for f in feeds if f.get("Feed", {}).get("enabled")
                    ]),
                    "organizations": server_stats.get("org_count", 0),
                }
            except Exception as e:
                stats["misp"] = {"error": str(e)}

        if self.opencti:
            try:
                connectors = self.opencti.connector.list()
                stats["opencti"] = {
                    "active_connectors": len([
                        c for c in connectors if c.get("active")
                    ]),
                    "total_connectors": len(connectors),
                }
            except Exception as e:
                stats["opencti"] = {"error": str(e)}

        return stats


def main():
    parser = argparse.ArgumentParser(description="TIP Management Tool")
    parser.add_argument("--misp-url", default="", help="MISP URL")
    parser.add_argument("--misp-key", default="", help="MISP API key")
    parser.add_argument("--opencti-url", default="", help="OpenCTI URL")
    parser.add_argument("--opencti-token", default="", help="OpenCTI token")
    parser.add_argument("--check-health", action="store_true")
    parser.add_argument("--configure-feeds", action="store_true")
    parser.add_argument("--platform-stats", action="store_true")
    parser.add_argument("--output", default="tip_report.json", help="Output file")

    args = parser.parse_args()
    manager = TIPManager(args.misp_url, args.misp_key, args.opencti_url, args.opencti_token)

    result = {}
    if args.check_health:
        result = manager.check_health()
    elif args.configure_feeds:
        result = manager.configure_feeds()
    elif args.platform_stats:
        result = manager.get_platform_stats()

    print(json.dumps(result, indent=2, default=str))
    with open(args.output, "w") as f:
        json.dump(result, f, indent=2, default=str)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Vulnerability dashboard builder using DefectDojo API.

Queries DefectDojo REST API v2 for findings, products, and engagements
to build vulnerability management dashboards and metrics.
"""

import json
import datetime
import os
import collections

try:
    import requests
    HAS_REQUESTS = True
except ImportError:
    HAS_REQUESTS = False


class DefectDojoClient:
    """Client for DefectDojo REST API v2."""

    def __init__(self, url=None, api_key=None):
        self.url = (url or os.environ.get("DEFECTDOJO_URL", "http://localhost:8080")).rstrip("/")
        self.api_key = api_key or os.environ.get("DEFECTDOJO_API_KEY", "")
        self.headers = {
            "Authorization": "Token " + self.api_key,
            "Content-Type": "application/json",
        }

    def _get(self, endpoint, params=None):
        if not HAS_REQUESTS or not self.api_key:
            return {"error": "requests not available or no API key"}
        try:
            resp = requests.get(
                self.url + "/api/v2/" + endpoint,
                headers=self.headers, params=params, timeout=15
            )
            if resp.status_code == 200:
                return resp.json()
            return {"error": "HTTP {}".format(resp.status_code)}
        except Exception as e:
            return {"error": str(e)}

    def get_findings(self, severity=None, active=True, limit=100):
        params = {"active": active, "limit": limit}
        if severity:
            params["severity"] = severity
        return self._get("findings/", params)

    def get_products(self, limit=100):
        return self._get("products/", {"limit": limit})

    def get_engagements(self, product_id=None, limit=100):
        params = {"limit": limit}
        if product_id:
            params["product"] = product_id
        return self._get("engagements/", params)

    def get_finding_count_by_severity(self):
        result = {}
        for sev in ["Critical", "High", "Medium", "Low", "Info"]:
            data = self._get("findings/", {"severity": sev, "active": True, "limit": 1})
            if isinstance(data, dict) and "count" in data:
                result[sev] = data["count"]
        return result

    def import_scan(self, product_id, engagement_id, scan_type, file_path):
        if not HAS_REQUESTS or not self.api_key:
            return {"error": "requests not available or no API key"}
        try:
            with open(file_path, "rb") as f:
                resp = requests.post(
                    self.url + "/api/v2/import-scan/",
                    headers={"Authorization": "Token " + self.api_key},
                    data={
                        "product": product_id,
                        "engagement": engagement_id,
                        "scan_type": scan_type,
                        "active": True,
                        "verified": False,
                    },
                    files={"file": f},
                    timeout=60,
                )
            if resp.status_code in (200, 201):
                return resp.json()
            return {"error": "HTTP {}".format(resp.status_code)}
        except Exception as e:
            return {"error": str(e)}


def build_dashboard_data(findings):
    """Build dashboard metrics from findings list."""
    if not isinstance(findings, dict) or "results" not in findings:
        return {"error": "Invalid findings data"}

    results = findings["results"]
    severity_counts = collections.Counter()
    product_counts = collections.Counter()
    age_sum = 0
    overdue_count = 0
    now = datetime.datetime.now(datetime.timezone.utc)

    for f in results:
        severity_counts[f.get("severity", "Unknown")] += 1
        product_counts[f.get("test", {}).get("engagement", {}).get("product", {}).get("name", "Unknown")] += 1
        if f.get("date"):
            try:
                created = datetime.datetime.fromisoformat(f["date"])
                if created.tzinfo is None:
                    created = created.replace(tzinfo=datetime.timezone.utc)
                age = (now - created).days
                age_sum += age
                sla = {"Critical": 7, "High": 30, "Medium": 90, "Low": 180}.get(f.get("severity", ""), 999)
                if age > sla:
                    overdue_count += 1
            except ValueError:
                pass

    total = len(results)
    return {
        "total_active_findings": total,
        "by_severity": dict(severity_counts),
        "by_product": dict(product_counts.most_common(10)),
        "avg_age_days": round(age_sum / max(total, 1), 1),
        "overdue_count": overdue_count,
        "sla_compliance_pct": round((total - overdue_count) / max(total, 1) * 100, 1),
    }


SUPPORTED_SCAN_TYPES = [
    "Nessus Scan", "Qualys Scan", "Burp REST API",
    "ZAP Scan", "Trivy Scan", "Snyk Scan",
    "Semgrep JSON Report", "SARIF", "Generic Findings Import",
    "Anchore Grype", "Nuclei Scan", "Checkov Scan",
]


if __name__ == "__main__":
    print("=" * 60)
    print("Vulnerability Dashboard with DefectDojo")
    print("REST API v2 queries, severity metrics, SLA tracking")
    print("=" * 60)
    print("  requests available: {}".format(HAS_REQUESTS))

    client = DefectDojoClient()

    print("\n--- Supported Scan Types ---")
    for st in SUPPORTED_SCAN_TYPES:
        print("  - {}".format(st))

    print("\n--- API Endpoints ---")
    endpoints = [
        ("GET", "/api/v2/findings/", "List findings"),
        ("GET", "/api/v2/products/", "List products"),
        ("GET", "/api/v2/engagements/", "List engagements"),
        ("POST", "/api/v2/import-scan/", "Import scan results"),
        ("POST", "/api/v2/reimport-scan/", "Re-import scan results"),
    ]
    for method, path, desc in endpoints:
        print("  {} {:30s} {}".format(method, path, desc))

    demo_findings = {
        "count": 5,
        "results": [
            {"severity": "Critical", "title": "SQL Injection", "date": "2025-01-10", "test": {"engagement": {"product": {"name": "WebApp"}}}},
            {"severity": "High", "title": "XSS", "date": "2025-01-15", "test": {"engagement": {"product": {"name": "WebApp"}}}},
            {"severity": "Medium", "title": "Missing Headers", "date": "2024-12-01", "test": {"engagement": {"product": {"name": "API"}}}},
            {"severity": "Low", "title": "Cookie flag", "date": "2025-02-01", "test": {"engagement": {"product": {"name": "API"}}}},
            {"severity": "Critical", "title": "RCE", "date": "2025-02-20", "test": {"engagement": {"product": {"name": "WebApp"}}}},
        ],
    }

    dashboard = build_dashboard_data(demo_findings)
    print("\n--- Dashboard ---")
    for k, v in dashboard.items():
        print("  {}: {}".format(k, v))

    print("\n" + json.dumps({"findings_analyzed": demo_findings["count"]}, indent=2))

#!/usr/bin/env python3
"""IOC Collection Agent - Extracts, enriches, and exports indicators of compromise."""

import json
import re
import logging
import argparse
from datetime import datetime

import requests
from stix2 import Indicator, Bundle

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

IPV4_PATTERN = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")
DOMAIN_PATTERN = re.compile(r"\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b")
SHA256_PATTERN = re.compile(r"\b[a-fA-F0-9]{64}\b")
MD5_PATTERN = re.compile(r"\b[a-fA-F0-9]{32}\b")
URL_PATTERN = re.compile(r"https?://[^\s\"'<>]+")


def extract_iocs_from_text(text):
    """Extract IOCs (IPs, domains, hashes, URLs) from unstructured text."""
    iocs = {
        "ipv4": list(set(IPV4_PATTERN.findall(text))),
        "domain": list(set(DOMAIN_PATTERN.findall(text))),
        "sha256": list(set(SHA256_PATTERN.findall(text))),
        "md5": list(set(MD5_PATTERN.findall(text))),
        "url": list(set(URL_PATTERN.findall(text))),
    }
    total = sum(len(v) for v in iocs.values())
    logger.info("Extracted %d IOCs from text input", total)
    return iocs


def extract_iocs_from_file(file_path):
    """Extract IOCs from a file (text report, log file, etc.)."""
    with open(file_path, "r", errors="ignore") as f:
        content = f.read()
    return extract_iocs_from_text(content)


def enrich_ip_virustotal(ip_address, api_key):
    """Enrich an IP address using VirusTotal API."""
    url = f"https://www.virustotal.com/api/v3/ip_addresses/{ip_address}"
    headers = {"x-apikey": api_key}
    resp = requests.get(url, headers=headers, timeout=30)
    if resp.status_code == 200:
        data = resp.json()["data"]["attributes"]
        result = {
            "ip": ip_address,
            "malicious": data.get("last_analysis_stats", {}).get("malicious", 0),
            "country": data.get("country", "unknown"),
            "asn": data.get("asn", 0),
            "as_owner": data.get("as_owner", "unknown"),
        }
        logger.info("VT enrichment for %s: %d malicious detections", ip_address, result["malicious"])
        return result
    return {"ip": ip_address, "error": resp.status_code}


def enrich_hash_malwarebazaar(file_hash):
    """Enrich a file hash using MalwareBazaar API."""
    url = "https://mb-api.abuse.ch/api/v1/"
    resp = requests.post(url, data={"query": "get_info", "hash": file_hash}, timeout=30)
    result = resp.json()
    if result.get("query_status") == "ok":
        sample = result["data"][0]
        return {
            "hash": file_hash,
            "family": sample.get("signature", "unknown"),
            "file_type": sample.get("file_type", "unknown"),
            "tags": sample.get("tags", []),
            "first_seen": sample.get("first_seen"),
        }
    return {"hash": file_hash, "status": "not_found"}


def enrich_domain_abuseipdb(domain, api_key):
    """Check domain reputation via AbuseIPDB."""
    url = "https://api.abuseipdb.com/api/v2/check"
    headers = {"Key": api_key, "Accept": "application/json"}
    resp = requests.get(url, headers=headers, params={"ipAddress": domain}, timeout=30)
    if resp.status_code == 200:
        data = resp.json()["data"]
        return {
            "domain": domain,
            "abuse_confidence": data.get("abuseConfidenceScore", 0),
            "total_reports": data.get("totalReports", 0),
            "country": data.get("countryCode", "unknown"),
        }
    return {"domain": domain, "error": resp.status_code}


def score_ioc(ioc_type, enrichment_data):
    """Assign confidence score (0-100) based on enrichment results."""
    if ioc_type == "ipv4":
        malicious_count = enrichment_data.get("malicious", 0)
        if malicious_count >= 10:
            return 95
        elif malicious_count >= 5:
            return 80
        elif malicious_count >= 1:
            return 60
        return 30
    elif ioc_type in ("sha256", "md5"):
        if enrichment_data.get("family") and enrichment_data["family"] != "unknown":
            return 95
        return 50
    return 50


def export_stix_bundle(iocs_with_scores, output_path):
    """Export IOCs as a STIX 2.1 bundle."""
    pattern_map = {
        "ipv4": lambda v: f"[ipv4-addr:value = '{v}']",
        "domain": lambda v: f"[domain-name:value = '{v}']",
        "url": lambda v: f"[url:value = '{v}']",
        "sha256": lambda v: f"[file:hashes.'SHA-256' = '{v}']",
        "md5": lambda v: f"[file:hashes.MD5 = '{v}']",
    }
    stix_indicators = []
    for ioc in iocs_with_scores:
        ioc_type = ioc["type"]
        pattern_fn = pattern_map.get(ioc_type)
        if pattern_fn:
            indicator = Indicator(
                name=f"{ioc_type}: {ioc['value']}",
                pattern=pattern_fn(ioc["value"]),
                pattern_type="stix",
                valid_from=datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
                confidence=ioc.get("confidence", 50),
                labels=[ioc_type],
            )
            stix_indicators.append(indicator)

    bundle = Bundle(objects=stix_indicators)
    with open(output_path, "w") as f:
        f.write(bundle.serialize(pretty=True))
    logger.info("STIX bundle exported: %d indicators to %s", len(stix_indicators), output_path)


def generate_ioc_report(iocs_with_scores):
    """Print a formatted IOC report."""
    lines = [
        "INDICATOR OF COMPROMISE REPORT",
        "=" * 40,
        f"Date: {datetime.utcnow().strftime('%Y-%m-%d %H:%M UTC')}",
        f"Total IOCs: {len(iocs_with_scores)}",
        "",
    ]
    for ioc_type in ["ipv4", "domain", "sha256", "md5", "url"]:
        typed = [i for i in iocs_with_scores if i["type"] == ioc_type]
        if typed:
            lines.append(f"\n{ioc_type.upper()} ({len(typed)}):")
            for ioc in typed[:10]:
                lines.append(f"  {ioc['value'][:60]:60s} Confidence: {ioc.get('confidence', 'N/A')}")
    print("\n".join(lines))


def main():
    parser = argparse.ArgumentParser(description="IOC Collection Agent")
    parser.add_argument("--input-file", help="File to extract IOCs from")
    parser.add_argument("--input-text", help="Text string to extract IOCs from")
    parser.add_argument("--vt-key", help="VirusTotal API key for enrichment")
    parser.add_argument("--output", default="ioc_bundle.json", help="STIX bundle output")
    args = parser.parse_args()

    raw_iocs = {}
    if args.input_file:
        raw_iocs = extract_iocs_from_file(args.input_file)
    elif args.input_text:
        raw_iocs = extract_iocs_from_text(args.input_text)

    iocs_with_scores = []
    for ioc_type, values in raw_iocs.items():
        for value in values:
            entry = {"type": ioc_type, "value": value, "confidence": 50}
            if ioc_type == "ipv4" and args.vt_key:
                enrichment = enrich_ip_virustotal(value, args.vt_key)
                entry["confidence"] = score_ioc("ipv4", enrichment)
                entry["enrichment"] = enrichment
            elif ioc_type in ("sha256", "md5"):
                enrichment = enrich_hash_malwarebazaar(value)
                entry["confidence"] = score_ioc(ioc_type, enrichment)
                entry["enrichment"] = enrichment
            iocs_with_scores.append(entry)

    generate_ioc_report(iocs_with_scores)
    export_stix_bundle(iocs_with_scores, args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Threat intelligence collection agent using MISP/PyMISP.

Connects to MISP instances to collect, filter, and export threat intelligence
including events, attributes, and feeds via the PyMISP REST API client.
"""

import json
import os
import datetime

try:
    from pymisp import PyMISP
    HAS_PYMISP = True
except ImportError:
    HAS_PYMISP = False


def init_misp(url=None, key=None):
    """Initialize PyMISP client."""
    url = url or os.environ.get("MISP_URL", "https://misp.example.org")
    key = key or os.environ.get("MISP_API_KEY", "")
    if not HAS_PYMISP:
        return None
    return PyMISP(url, key, ssl=True)


def search_events(misp, tags=None, date_from=None, published=True, limit=50):
    """Search MISP events by tags and date."""
    if not misp:
        return {"error": "PyMISP not available"}
    kwargs = {"limit": limit, "published": published, "pythonify": True}
    if tags:
        kwargs["tags"] = tags
    if date_from:
        kwargs["date_from"] = date_from
    try:
        events = misp.search("events", **kwargs)
        return [
            {
                "id": e.id,
                "uuid": e.uuid,
                "info": e.info,
                "date": str(e.date),
                "threat_level": {1: "High", 2: "Medium", 3: "Low", 4: "Undefined"}.get(e.threat_level_id, "?"),
                "analysis": {0: "Initial", 1: "Ongoing", 2: "Complete"}.get(e.analysis, "?"),
                "attribute_count": e.attribute_count,
                "org": e.Orgc.name if hasattr(e, "Orgc") and e.Orgc else "",
                "tags": [t.name for t in (e.tags or [])],
            }
            for e in events
        ]
    except Exception as e:
        return {"error": str(e)}


def extract_attributes(misp, event_id, attr_type=None):
    """Extract attributes from a MISP event."""
    if not misp:
        return {"error": "PyMISP not available"}
    try:
        kwargs = {"eventid": event_id, "pythonify": True}
        if attr_type:
            kwargs["type_attribute"] = attr_type
        attrs = misp.search("attributes", **kwargs)
        return [
            {
                "type": a.type,
                "value": a.value,
                "category": a.category,
                "to_ids": a.to_ids,
                "comment": a.comment or "",
                "timestamp": str(datetime.datetime.fromtimestamp(int(a.timestamp))),
            }
            for a in attrs
        ]
    except Exception as e:
        return {"error": str(e)}


def collect_iocs_by_type(misp, ioc_types, date_from=None, limit=500):
    """Collect IOCs filtered by attribute type."""
    if not misp:
        return {"error": "PyMISP not available"}
    results = {}
    for ioc_type in ioc_types:
        try:
            kwargs = {"type_attribute": ioc_type, "to_ids": True, "pythonify": True, "limit": limit}
            if date_from:
                kwargs["date_from"] = date_from
            attrs = misp.search("attributes", **kwargs)
            results[ioc_type] = [
                {"value": a.value, "event_id": a.event_id, "comment": a.comment or ""}
                for a in attrs
            ]
        except Exception as e:
            results[ioc_type] = {"error": str(e)}
    return results


def list_feeds(misp):
