"""Pass-the-Ticket attack detection agent using Windows event log analysis."""

import json
import argparse
from datetime import datetime


def detect_ptt_events(log_file):
    """Analyze Windows Security logs for Pass-the-Ticket indicators."""
    detections = []
    try:
        with open(log_file, "r") as f:
            events = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        return [{"error": str(e)}]

    for event in events:
        eid = str(event.get("EventID", ""))
        if eid == "4768":
            if event.get("TicketEncryptionType") == "0x17":
                detections.append({
                    "event_id": eid,
                    "type": "TGT_request_rc4",
                    "account": event.get("TargetUserName", ""),
                    "source_ip": event.get("IpAddress", ""),
                    "severity": "HIGH",
                    "note": "RC4 TGT request may indicate golden ticket",
                })
        elif eid == "4769":
            if event.get("TicketEncryptionType") == "0x17":
                detections.append({
                    "event_id": eid,
                    "type": "service_ticket_rc4",
                    "account": event.get("TargetUserName", ""),
                    "service": event.get("ServiceName", ""),
                    "severity": "MEDIUM",
                    "note": "RC4 service ticket — potential Kerberoasting or PTT",
                })
        elif eid == "4624":
            if event.get("LogonType") == "3" and event.get("AuthenticationPackageName") == "Kerberos":
                source = event.get("IpAddress", "")
                detections.append({
                    "event_id": eid,
                    "type": "network_logon_kerberos",
                    "account": event.get("TargetUserName", ""),
                    "source_ip": source,
                    "severity": "INFO",
                    "note": "Kerberos network logon — correlate with TGT anomalies",
                })
    return detections


def generate_sigma_rules():
    """Generate Sigma detection rules for Pass-the-Ticket."""
    rules = [
        {
            "title": "Pass-the-Ticket via RC4 Encryption Downgrade",
            "logsource": {"product": "windows", "service": "security"},
            "detection": {
                "selection": {"EventID": [4768, 4769], "TicketEncryptionType": "0x17"},
                "condition": "selection",
            },
            "level": "high",
            "tags": ["attack.lateral_movement", "attack.t1550.003"],
        },
        {
            "title": "Anomalous Kerberos TGT Request from Non-Domain Controller",
            "logsource": {"product": "windows", "service": "security"},
            "detection": {
                "selection": {"EventID": 4768},
                "filter": {"IpAddress|startswith": ["::1", "127."]},
                "condition": "selection and not filter",
            },
            "level": "medium",
            "tags": ["attack.credential_access", "attack.t1558"],
        },
    ]
    return rules


def generate_hunt_queries():
    """Generate threat hunting queries for PTT detection."""
    return {
        "splunk": [
            'index=wineventlog EventCode=4768 TicketEncryptionType=0x17 | stats count by Account_Name, src_ip',
            'index=wineventlog EventCode=4769 ServiceName!="krbtgt" TicketEncryptionType=0x17 | table _time Account_Name ServiceName',
        ],
        "kql": [
            'SecurityEvent | where EventID == 4768 | where TicketEncryptionType == "0x17" | summarize count() by TargetAccount, IpAddress',
            'SecurityEvent | where EventID == 4769 | where TicketEncryptionType == "0x17" | project TimeGenerated, TargetAccount, ServiceName',
        ],
    }


def run_detection(log_file=None):
    """Execute Pass-the-Ticket detection analysis."""
    print(f"\n{'='*60}")
    print(f"  PASS-THE-TICKET DETECTION ANALYSIS")
    print(f"  Generated: {datetime.utcnow().isoformat()} UTC")
    print(f"{'='*60}\n")

    if log_file:
        events = detect_ptt_events(log_file)
        print(f"--- EVENT ANALYSIS ({len(events)} detections) ---")
        for e in events[:15]:
            if "error" not in e:
                print(f"  [{e['severity']}] {e['type']}: {e.get('account', 'N/A')} from {e.get('source_ip', 'N/A')}")

    rules = generate_sigma_rules()
    print(f"\n--- SIGMA RULES ({len(rules)}) ---")
    for r in rules:
        print(f"  [{r['level'].upper()}] {r['title']}")

    queries = generate_hunt_queries()
    print(f"\n--- HUNT QUERIES ---")
    for platform, qlist in queries.items():
        print(f"  {platform.upper()}:")
        for q in qlist:
            print(f"    {q[:80]}...")

    return {"detections": events if log_file else [], "sigma_rules": rules, "hunt_queries": queries}


def main():
    parser = argparse.ArgumentParser(description="Pass-the-Ticket Detection Agent")
    parser.add_argument("--log-file", help="Windows event log JSON export")
    parser.add_argument("--output", help="Save report to JSON file")
    args = parser.parse_args()

    report = run_detection(args.log_file)
    if args.output:
        with open(args.output, "w") as f:
            json.dump(report, f, indent=2, default=str)
        print(f"\n[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Phishing Incident Response Agent - Analyzes phishing emails and automates response actions."""

import json
import re
import email
import hashlib
import logging
import argparse
from email import policy
from datetime import datetime

import requests

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


def parse_email_file(eml_path):
    """Parse an EML file and extract header and body information."""
    with open(eml_path, "rb") as f:
        msg = email.message_from_binary_file(f, policy=policy.default)
    parsed = {
        "subject": msg["Subject"],
        "from": msg["From"],
        "to": msg["To"],
        "date": msg["Date"],
        "message_id": msg["Message-ID"],
        "return_path": msg["Return-Path"],
        "reply_to": msg["Reply-To"],
        "received_headers": msg.get_all("Received", []),
        "authentication_results": msg.get("Authentication-Results", ""),
        "spf": "",
        "dkim": "",
        "dmarc": "",
    }
    auth_results = parsed["authentication_results"]
    if "spf=pass" in auth_results:
        parsed["spf"] = "pass"
    elif "spf=fail" in auth_results:
        parsed["spf"] = "fail"
    if "dkim=pass" in auth_results:
        parsed["dkim"] = "pass"
    elif "dkim=fail" in auth_results:
        parsed["dkim"] = "fail"
    if "dmarc=pass" in auth_results:
        parsed["dmarc"] = "pass"
    elif "dmarc=fail" in auth_results:
        parsed["dmarc"] = "fail"

    logger.info("Parsed email: Subject='%s' From='%s'", parsed["subject"], parsed["from"])
    return parsed, msg


def extract_urls(msg):
    """Extract all URLs from email body."""
    body = ""
    if msg.is_multipart():
        for part in msg.walk():
            if part.get_content_type() in ("text/plain", "text/html"):
                body += part.get_content()
    else:
        body = msg.get_content()
    urls = re.findall(r'https?://[^\s"\'<>]+', body)
    unique_urls = list(set(urls))
    logger.info("Extracted %d unique URLs", len(unique_urls))
    return unique_urls


def extract_attachments(msg):
    """Extract and hash email attachments."""
    attachments = []
    for part in msg.walk():
        if part.get_content_disposition() == "attachment":
            filename = part.get_filename()
            content = part.get_payload(decode=True)
            if content:
                sha256 = hashlib.sha256(content).hexdigest()
                md5 = hashlib.md5(content).hexdigest()
                attachments.append({
                    "filename": filename,
                    "content_type": part.get_content_type(),
                    "size": len(content),
                    "sha256": sha256,
                    "md5": md5,
                })
                logger.info("Attachment: %s (SHA256: %s)", filename, sha256[:16])
    return attachments


def check_url_virustotal(url, api_key):
    """Check URL reputation on VirusTotal."""
    import base64
    url_id = base64.urlsafe_b64encode(url.encode()).decode().strip("=")
    vt_url = f"https://www.virustotal.com/api/v3/urls/{url_id}"
    headers = {"x-apikey": api_key}
    resp = requests.get(vt_url, headers=headers, timeout=30)
    if resp.status_code == 200:
        stats = resp.json()["data"]["attributes"]["last_analysis_stats"]
        return {
            "url": url,
            "malicious": stats.get("malicious", 0),
            "suspicious": stats.get("suspicious", 0),
            "harmless": stats.get("harmless", 0),
        }
    return {"url": url, "error": resp.status_code}


def check_url_urlscan(url):
    """Submit URL to urlscan.io for analysis."""
    resp = requests.post(
        "https://urlscan.io/api/v1/scan/",
        json={"url": url, "visibility": "private"},
        headers={"Content-Type": "application/json"},
        timeout=30,
    )
    if resp.status_code == 200:
        return resp.json()
    return {"url": url, "error": resp.status_code}


def check_hash_virustotal(file_hash, api_key):
    """Check file hash reputation on VirusTotal."""
    url = f"https://www.virustotal.com/api/v3/files/{file_hash}"
    headers = {"x-apikey": api_key}
    resp = requests.get(url, headers=headers, timeout=30)
    if resp.status_code == 200:
        attrs = resp.json()["data"]["attributes"]
        return {
            "hash": file_hash,
            "malicious": attrs["last_analysis_stats"].get("malicious", 0),
            "threat_name": attrs.get("popular_threat_classification", {}).get("suggested_threat_label", ""),
        }
    return {"hash": file_hash, "status": "not_found"}


def assess_phishing_severity(parsed_email, url_results, attachment_results):
    """Assess overall severity of the phishing email."""
    severity = "Low"
    indicators = []
    if parsed_email.get("spf") == "fail":
        indicators.append("SPF failed")
        severity = "Medium"
    if parsed_email.get("dkim") == "fail":
        indicators.append("DKIM failed")
        severity = "Medium"
    if parsed_email.get("dmarc") == "fail":
        indicators.append("DMARC failed")
        severity = "Medium"
    for url_result in url_results:
        if url_result.get("malicious", 0) > 0:
            indicators.append(f"Malicious URL: {url_result['url'][:50]}")
            severity = "Critical"
    for att_result in attachment_results:
        if att_result.get("malicious", 0) > 0:
            indicators.append(f"Malicious attachment: {att_result['hash'][:16]}")
            severity = "Critical"
    return {"severity": severity, "indicators": indicators}


def generate_phishing_report(parsed_email, urls, attachments, url_results, att_results, assessment):
    """Generate phishing incident response report."""
    report = {
        "timestamp": datetime.utcnow().isoformat(),
        "email_headers": parsed_email,
        "urls_found": urls,
        "attachments": attachments,
        "url_analysis": url_results,
        "attachment_analysis": att_results,
        "severity_assessment": assessment,
    }
    print(f"PHISHING IR REPORT - Severity: {assessment['severity']}")
