    "D3E037E1-3EB8-44C8-A917-57927947596D": {"name": "Block JS/VBS launching executables", "mode": 1},
    "5BEB7EFE-FD9A-4556-801D-275E5FFC04CC": {"name": "Block obfuscated scripts", "mode": 1},
    "92E97FA1-2EDF-4476-BDD6-9DD0B4DDDC7B": {"name": "Block Win32 API from macros", "mode": 1},
    "9E6C4E1F-7D60-472F-BA1A-A39EF669E4B2": {"name": "Block LSASS credential stealing", "mode": 1},
    "D1E49AAC-8F56-4280-B9BA-993A6D77406C": {"name": "Block PSExec/WMI processes", "mode": 1},
    "B2B3F03D-6A65-4F7B-A9C7-1C7EF74A9BA4": {"name": "Block untrusted USB processes", "mode": 1},
    "E6DB77E5-3DF2-4CF1-B95A-636979351E5B": {"name": "Block WMI persistence", "mode": 1},
    "56A863A9-875E-4185-98A7-B882C64B5CE5": {"name": "Block vulnerable signed drivers", "mode": 1},
}


def collect_defender_settings() -> dict:
    """Collect current Defender settings via PowerShell."""
    ps_cmd = """
    $prefs = Get-MpPreference
    $status = Get-MpComputerStatus
    $result = @{
        Preferences = @{
            RealTimeProtectionEnabled = $prefs.DisableRealtimeMonitoring -eq $false
            BehaviorMonitoringEnabled = $prefs.DisableBehaviorMonitoring -eq $false
            IoavProtectionEnabled = $prefs.DisableIOAVProtection -eq $false
            AntispywareEnabled = $status.AntispywareEnabled
            AntivirusEnabled = $status.AntivirusEnabled
            MAPSReporting = $prefs.MAPSReporting
            SubmitSamplesConsent = $prefs.SubmitSamplesConsent
            PUAProtection = $prefs.PUAProtection
            DisableBlockAtFirstSeen = $prefs.DisableBlockAtFirstSeen
            CloudBlockLevel = $prefs.CloudBlockLevel
            CloudExtendedTimeout = $prefs.CloudExtendedTimeout
            EnableNetworkProtection = $prefs.EnableNetworkProtection
            EnableControlledFolderAccess = $prefs.EnableControlledFolderAccess
            SignatureUpdateInterval = $prefs.SignatureUpdateInterval
        }
        ASRRules = @{}
        Status = @{
            AMEngineVersion = $status.AMEngineVersion
            AMProductVersion = $status.AMProductVersion
            AntispywareSignatureVersion = $status.AntispywareSignatureVersion
            AntivirusSignatureVersion = $status.AntivirusSignatureVersion
            AntivirusSignatureLastUpdated = $status.AntivirusSignatureLastUpdated.ToString('o')
            FullScanEndTime = if($status.FullScanEndTime) { $status.FullScanEndTime.ToString('o') } else { 'Never' }
            QuickScanEndTime = if($status.QuickScanEndTime) { $status.QuickScanEndTime.ToString('o') } else { 'Never' }
            RealTimeProtectionEnabled = $status.RealTimeProtectionEnabled
            TamperProtectionSource = $status.IsTamperProtected
        }
    }
    $ids = $prefs.AttackSurfaceReductionRules_Ids
    $actions = $prefs.AttackSurfaceReductionRules_Actions
    if ($ids -and $actions) {
        for ($i=0; $i -lt $ids.Count; $i++) {
            $result.ASRRules[$ids[$i].ToString().ToUpper()] = $actions[$i]
        }
    }
    $result | ConvertTo-Json -Depth 3
    """

    try:
        result = subprocess.run(
            ["powershell", "-NoProfile", "-Command", ps_cmd],
            capture_output=True, text=True, timeout=30,
        )
        if result.returncode == 0 and result.stdout.strip():
            return json.loads(result.stdout)
        else:
            return {"error": result.stderr or "Failed to collect Defender settings"}
    except FileNotFoundError:
        return {"error": "PowerShell not available (requires Windows)"}
    except subprocess.TimeoutExpired:
        return {"error": "PowerShell command timed out"}
    except json.JSONDecodeError as e:
        return {"error": f"Failed to parse PowerShell output: {e}"}


def audit_settings(settings: dict) -> dict:
    """Audit collected settings against recommended baseline."""
    findings = {
        "compliant": [],
        "non_compliant": [],
        "asr_rules": {
            "enabled_block": [],
            "enabled_audit": [],
            "disabled": [],
            "missing": [],
        },
        "score": 0.0,
    }

    prefs = settings.get("Preferences", {})
    total_checks = 0
    passed_checks = 0

    for setting, expected in RECOMMENDED_SETTINGS.items():
        total_checks += 1
        actual = prefs.get(setting)

        if actual == expected:
            passed_checks += 1
            findings["compliant"].append({
                "setting": setting,
                "expected": expected,
                "actual": actual,
            })
        else:
            findings["non_compliant"].append({
                "setting": setting,
                "expected": expected,
                "actual": actual,
                "severity": "high" if setting in (
                    "RealTimeProtectionEnabled", "AntivirusEnabled",
                    "EnableNetworkProtection", "MAPSReporting",
                ) else "medium",
            })

    asr_rules = settings.get("ASRRules", {})
    for rule_guid, rule_info in RECOMMENDED_ASR_RULES.items():
        total_checks += 1
        mode = asr_rules.get(rule_guid)

        if mode == 1:
            passed_checks += 1
            findings["asr_rules"]["enabled_block"].append({
                "guid": rule_guid, "name": rule_info["name"],
            })
        elif mode == 2:
            findings["asr_rules"]["enabled_audit"].append({
                "guid": rule_guid, "name": rule_info["name"],
            })
        elif mode == 0:
            findings["asr_rules"]["disabled"].append({
                "guid": rule_guid, "name": rule_info["name"],
            })
        else:
            findings["asr_rules"]["missing"].append({
                "guid": rule_guid, "name": rule_info["name"],
            })

    if total_checks > 0:
        findings["score"] = round((passed_checks / total_checks) * 100, 2)

    return findings


def generate_report(settings: dict, findings: dict, output_path: str) -> None:
    """Generate configuration audit report."""
    report = {
        "report_generated": datetime.utcnow().isoformat() + "Z",
        "defender_status": settings.get("Status", {}),
        "compliance_score": findings["score"],
        "total_compliant": len(findings["compliant"]),
        "total_non_compliant": len(findings["non_compliant"]),
        "asr_summary": {
            "block_mode": len(findings["asr_rules"]["enabled_block"]),
            "audit_mode": len(findings["asr_rules"]["enabled_audit"]),
            "disabled": len(findings["asr_rules"]["disabled"]),
            "not_configured": len(findings["asr_rules"]["missing"]),
        },
        "non_compliant_settings": findings["non_compliant"],
        "asr_details": findings["asr_rules"],
    }

    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)


if __name__ == "__main__":
    output_dir = sys.argv[1] if len(sys.argv) > 1 else "."

    print("Collecting Microsoft Defender settings...")
    settings = collect_defender_settings()

    if "error" in settings:
        print(f"Error: {settings['error']}")
        print("This tool requires Windows with Microsoft Defender for Endpoint.")
        sys.exit(1)

    print("Auditing against recommended baseline...")
    findings = audit_settings(settings)

    report_path = os.path.join(output_dir, "defender_audit_report.json")
    generate_report(settings, findings, report_path)
    print(f"Audit report: {report_path}")

    print(f"\n--- Defender Configuration Audit ---")
    print(f"Compliance Score: {findings['score']}%")
    print(f"Compliant settings: {len(findings['compliant'])}")
    print(f"Non-compliant: {len(findings['non_compliant'])}")
    print(f"\nASR Rules:")
    print(f"  Block mode: {len(findings['asr_rules']['enabled_block'])}")
    print(f"  Audit mode: {len(findings['asr_rules']['enabled_audit'])}")
    print(f"  Disabled: {len(findings['asr_rules']['disabled'])}")
    print(f"  Not configured: {len(findings['asr_rules']['missing'])}")

    if findings["non_compliant"]:
        print(f"\nNon-compliant settings requiring remediation:")
        for item in findings["non_compliant"]:
            print(f"  [{item['severity'].upper()}] {item['setting']}: expected={item['expected']}, actual={item['actual']}")

#!/usr/bin/env python3
"""Windows event logging configuration audit agent."""

import json
import argparse
import subprocess
from datetime import datetime


CRITICAL_AUDIT_POLICIES = {
    "Logon/Logoff": {"Logon": "Success,Failure", "Logoff": "Success"},
    "Account Logon": {"Credential Validation": "Success,Failure", "Kerberos Authentication Service": "Success,Failure"},
    "Object Access": {"File System": "Success,Failure", "Registry": "Success,Failure"},
    "Privilege Use": {"Sensitive Privilege Use": "Success,Failure"},
    "Process Tracking": {"Process Creation": "Success"},
    "DS Access": {"Directory Service Access": "Success,Failure"},
    "Policy Change": {"Audit Policy Change": "Success,Failure", "Authentication Policy Change": "Success"},
}


def get_audit_policy():
    """Get current advanced audit policy configuration."""
    cmd = ["auditpol", "/get", "/category:*"]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
        lines = result.stdout.strip().split("\n")
        policies = {}
        current_category = ""
        for line in lines:
            stripped = line.strip()
            if not stripped or "Machine Name" in stripped or "Category" in stripped:
                continue
            if not stripped.startswith("  "):
                current_category = stripped
                policies[current_category] = {}
            else:
                parts = stripped.rsplit("  ", 1)
                if len(parts) == 2:
                    policies[current_category][parts[0].strip()] = parts[1].strip()
        return policies
    except (FileNotFoundError, subprocess.TimeoutExpired) as e:
        return {"error": str(e)}


def check_sysmon_installed():
    """Check if Sysmon is installed and running."""
    cmd = ["powershell", "-Command", "Get-Service Sysmon* | ConvertTo-Json"]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
        if result.stdout.strip():
            service = json.loads(result.stdout)
            if isinstance(service, list):
                service = service[0]
            return {"installed": True, "status": service.get("Status", ""),
                    "name": service.get("Name", "")}
        return {"installed": False, "severity": "HIGH",
                "recommendation": "Install Sysmon with SwiftOnSecurity config"}
    except (FileNotFoundError, json.JSONDecodeError):
        return {"installed": False}


def check_log_sizes():
    """Check event log maximum sizes."""
    logs = ["Security", "System", "Application", "Microsoft-Windows-Sysmon/Operational",
            "Microsoft-Windows-PowerShell/Operational"]
    results = []
    for log_name in logs:
        cmd = ["powershell", "-Command",
               f"(Get-WinEvent -ListLog '{log_name}' -ErrorAction SilentlyContinue).MaximumSizeInBytes"]
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            size_bytes = int(result.stdout.strip()) if result.stdout.strip() else 0
            size_mb = round(size_bytes / (1024 * 1024), 1)
            results.append({
                "log": log_name,
                "max_size_mb": size_mb,
                "severity": "MEDIUM" if size_mb < 100 else "INFO",
            })
        except (ValueError, subprocess.TimeoutExpired):
            results.append({"log": log_name, "error": "Cannot query"})
    return results


def check_powershell_logging():
    """Check PowerShell script block logging and transcription."""
    checks = {}
    for name, path in [
        ("ScriptBlockLogging", r"HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging"),
        ("Transcription", r"HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\Transcription"),
    ]:
        cmd = ["powershell", "-Command", f"Get-ItemProperty -Path '{path}' -ErrorAction SilentlyContinue | ConvertTo-Json"]
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            checks[name] = json.loads(result.stdout) if result.stdout.strip() else {"enabled": False}
        except (json.JSONDecodeError, subprocess.TimeoutExpired):
            checks[name] = {"enabled": False}
    return checks


def run_audit():
    """Execute Windows event logging audit."""
    print(f"\n{'='*60}")
    print(f"  WINDOWS EVENT LOGGING AUDIT")
    print(f"  Generated: {datetime.utcnow().isoformat()} UTC")
    print(f"{'='*60}\n")

    sysmon = check_sysmon_installed()
    print(f"--- SYSMON ---")
    print(f"  Installed: {sysmon.get('installed', False)}")
    print(f"  Status: {sysmon.get('status', 'N/A')}")

    logs = check_log_sizes()
    print(f"\n--- LOG SIZES ---")
    for l in logs:
        if "error" not in l:
            print(f"  {l['log']}: {l['max_size_mb']} MB [{l['severity']}]")

    ps_logging = check_powershell_logging()
    print(f"\n--- POWERSHELL LOGGING ---")
    for name, config in ps_logging.items():
        enabled = config.get("EnableScriptBlockLogging", config.get("EnableTranscripting", False))
        print(f"  {name}: {'Enabled' if enabled else 'Disabled'}")

    return {"sysmon": sysmon, "log_sizes": logs, "powershell": ps_logging}


def main():
    parser = argparse.ArgumentParser(description="Windows Event Logging Audit Agent")
    parser.add_argument("--audit", action="store_true", help="Run full audit")
    parser.add_argument("--output", help="Save report to JSON file")
    args = parser.parse_args()

    if args.audit:
        report = run_audit()
        if args.output:
            with open(args.output, "w") as f:
                json.dump(report, f, indent=2, default=str)
            print(f"\n[+] Report saved to {args.output}")
    else:
        parser.print_help()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Windows Event Logging Auditor - Checks current audit policy configuration."""

import json, subprocess, sys, os
from datetime import datetime


def get_audit_policy() -> dict:
    """Query current advanced audit policy via auditpol."""
    try:
        result = subprocess.run(
            ["auditpol", "/get", "/category:*"],
            capture_output=True, text=True, timeout=15,
        )
        if result.returncode != 0:
            return {"error": result.stderr}

        policies = {}
        current_category = ""
        for line in result.stdout.splitlines():
            line = line.strip()
            if not line:
                continue
            if "  " not in line and line.endswith(":"):
                continue
            parts = line.rsplit("  ", 1)
            if len(parts) == 2:
                name = parts[0].strip()
                setting = parts[1].strip()
                policies[name] = setting
        return policies
    except FileNotFoundError:
        return {"error": "auditpol not available (requires Windows)"}


RECOMMENDED = {
    "Credential Validation": "Success and Failure",
    "Security Group Management": "Success",
    "User Account Management": "Success and Failure",
    "Logon": "Success and Failure",
    "Logoff": "Success",
    "Special Logon": "Success",
    "Process Creation": "Success",
    "Audit Policy Change": "Success",
    "Sensitive Privilege Use": "Success and Failure",
}


if __name__ == "__main__":
    policies = get_audit_policy()
    if "error" in policies:
        print(f"Error: {policies['error']}")
        sys.exit(1)

    compliant = 0
    total = len(RECOMMENDED)
    for setting, expected in RECOMMENDED.items():
        actual = policies.get(setting, "No Auditing")
        status = "PASS" if expected in actual else "FAIL"
        if status == "PASS":
            compliant += 1
        print(f"[{status}] {setting}: {actual} (expected: {expected})")

    print(f"\nScore: {compliant}/{total} ({round(compliant/total*100)}%)")

#!/usr/bin/env python3
"""Zscaler Private Access (ZPA) ZTNA audit agent using ZPA API."""

import json
import sys
import argparse
from datetime import datetime

try:
    import requests
except ImportError:
    print("Install: pip install requests")
    sys.exit(1)


class ZPAClient:
    """Zscaler Private Access API client."""

    def __init__(self, client_id, client_secret, customer_id):
        self.base_url = "https://config.private.zscaler.com"
        self.customer_id = customer_id
        self.token = self._authenticate(client_id, client_secret)

    def _authenticate(self, client_id, client_secret):
        resp = requests.post(f"{self.base_url}/signin", json={
            "client_id": client_id, "client_secret": client_secret,
        }, timeout=30)
        resp.raise_for_status()
        return resp.json()["token"]

    def _get(self, endpoint):
        resp = requests.get(f"{self.base_url}/mgmtconfig/v1/admin/customers/{self.customer_id}/{endpoint}",
                            headers={"Authorization": f"Bearer {self.token}"}, timeout=30)
        resp.raise_for_status()
        return resp.json()

    def list_app_segments(self):
        return self._get("application")

    def list_server_groups(self):
        return self._get("serverGroup")

    def list_app_connectors(self):
        return self._get("connector")

    def list_access_policies(self):
        return self._get("policySet/rules")

    def list_segment_groups(self):
        return self._get("segmentGroup")


def audit_zpa_config(client):
    """Audit ZPA configuration for security posture."""
    findings = []
    apps = client.list_app_segments()
    for app in apps.get("list", []):
        if not app.get("enabled"):
            findings.append({
                "type": "disabled_app_segment",
                "name": app.get("name", ""),
                "severity": "LOW",
            })
        if app.get("bypassType") == "ALWAYS":
            findings.append({
                "type": "bypass_enabled",
                "name": app.get("name", ""),
                "severity": "HIGH",
                "recommendation": "Remove bypass to enforce ZPA inspection",
            })
    connectors = client.list_app_connectors()
    for conn in connectors.get("list", []):
        if conn.get("runtimeStatus") != "running":
            findings.append({
                "type": "connector_down",
                "name": conn.get("name", ""),
                "status": conn.get("runtimeStatus", ""),
                "severity": "CRITICAL",
            })
    return findings


def run_audit(client_id, client_secret, customer_id):
    """Execute ZPA ZTNA audit."""
    client = ZPAClient(client_id, client_secret, customer_id)
    print(f"\n{'='*60}")
    print(f"  ZSCALER PRIVATE ACCESS ZTNA AUDIT")
    print(f"  Generated: {datetime.utcnow().isoformat()} UTC")
    print(f"{'='*60}\n")

    apps = client.list_app_segments()
    app_list = apps.get("list", [])
    print(f"--- APPLICATION SEGMENTS ({len(app_list)}) ---")
    for a in app_list[:10]:
        print(f"  {a.get('name', '')}: enabled={a.get('enabled', '')} bypass={a.get('bypassType', '')}")

    connectors = client.list_app_connectors()
    conn_list = connectors.get("list", [])
    print(f"\n--- APP CONNECTORS ({len(conn_list)}) ---")
    for c in conn_list[:10]:
        print(f"  {c.get('name', '')}: {c.get('runtimeStatus', '')}")

    findings = audit_zpa_config(client)
    print(f"\n--- AUDIT FINDINGS ({len(findings)}) ---")
    for f in findings:
        print(f"  [{f['severity']}] {f['type']}: {f.get('name', '')}")

    return {"apps": len(app_list), "connectors": len(conn_list), "findings": findings}


def main():
    parser = argparse.ArgumentParser(description="ZPA ZTNA Audit Agent")
    parser.add_argument("--client-id", required=True, help="ZPA API client ID")
    parser.add_argument("--client-secret", required=True, help="ZPA API client secret")
    parser.add_argument("--customer-id", required=True, help="ZPA customer ID")
    parser.add_argument("--output", help="Save report to JSON file")
    args = parser.parse_args()

    report = run_audit(args.client_id, args.client_secret, args.customer_id)
    if args.output:
        with open(args.output, "w") as f:
            json.dump(report, f, indent=2, default=str)
        print(f"\n[+] Report saved to {args.output}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Zscaler Private Access (ZPA) - Deployment Audit and Compliance Checker

Queries ZPA Admin API to audit App Connector health, application segment
coverage, access policy configuration, and user activity for ZTNA compliance.

Requirements:
    pip install requests
"""

import json
import sys
import time
from datetime import datetime, timezone
from typing import Any

import requests

ZPA_BASE_URL = "https://config.private.zscaler.com"


class ZPAAuditor:
    """Audit Zscaler Private Access deployment configuration."""

    def __init__(self, client_id: str, client_secret: str, customer_id: str):
        self.client_id = client_id
        self.client_secret = client_secret
        self.customer_id = customer_id
        self.token = None
        self._authenticate()

    def _authenticate(self):
        """Authenticate with ZPA API."""
        resp = requests.post(
            f"{ZPA_BASE_URL}/signin",
            json={
                "apiKey": self.client_id,
                "username": self.client_secret,
                "password": self.customer_id
            },
            timeout=30
        )
        resp.raise_for_status()
        self.token = resp.json().get("token")
        print("[AUTH] Successfully authenticated with ZPA API")

    def _get(self, endpoint: str, params: dict = None) -> dict:
        """Make authenticated GET request to ZPA API."""
        headers = {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json"
        }
        resp = requests.get(
            f"{ZPA_BASE_URL}/mgmtconfig/v1/admin/customers/{self.customer_id}/{endpoint}",
            headers=headers,
            params=params or {},
            timeout=30
        )
        resp.raise_for_status()
        return resp.json()

    def audit_app_connectors(self) -> dict[str, Any]:
        """Audit App Connector deployment and health."""
        print("\n[1/5] Auditing App Connectors...")
        data = self._get("connector")
        connectors = data.get("list", [])

        stats = {
            "total": len(connectors),
            "healthy": 0,
            "unhealthy": 0,
            "groups": {},
            "version_distribution": {},
            "unhealthy_list": []
        }

        for conn in connectors:
            name = conn.get("name", "unknown")
            enabled = conn.get("enabled", False)
            runtime_status = conn.get("runtimeStatus", "UNKNOWN")
            version = conn.get("currentVersion", "unknown")
            group = conn.get("appConnectorGroupName", "ungrouped")

            stats["groups"][group] = stats["groups"].get(group, 0) + 1
            stats["version_distribution"][version] = stats["version_distribution"].get(version, 0) + 1

            if enabled and runtime_status == "ACTIVE":
                stats["healthy"] += 1
            else:
                stats["unhealthy"] += 1
                stats["unhealthy_list"].append({
                    "name": name, "status": runtime_status, "group": group
                })
                print(f"  [WARN] Unhealthy connector: {name} (status: {runtime_status})")

        print(f"  Total: {stats['total']}, Healthy: {stats['healthy']}, Unhealthy: {stats['unhealthy']}")
        print(f"  Groups: {stats['groups']}")

        # Check HA: each group should have >= 2 connectors
        for group, count in stats["groups"].items():
            if count < 2:
                print(f"  [CRITICAL] Group '{group}' has only {count} connector(s) - no HA!")

        return stats

    def audit_application_segments(self) -> dict[str, Any]:
        """Audit application segment configuration."""
        print("\n[2/5] Auditing Application Segments...")
        data = self._get("application")
        segments = data.get("list", [])

        stats = {
            "total": len(segments),
            "enabled": 0,
            "disabled": 0,
            "bypass_enabled": 0,
            "health_reporting": {"continuous": 0, "on_access": 0, "none": 0},
            "segments": []
        }

        for seg in segments:
            name = seg.get("name", "unknown")
            enabled = seg.get("enabled", False)
            bypass_type = seg.get("bypassType", "NEVER")
            health = seg.get("healthReporting", "NONE")
            domains = seg.get("domainNames", [])
            tcp_ports = seg.get("tcpPortRanges", [])

            if enabled:
                stats["enabled"] += 1
            else:
                stats["disabled"] += 1
                print(f"  [WARN] Disabled segment: {name}")

            if bypass_type != "NEVER":
                stats["bypass_enabled"] += 1
                print(f"  [WARN] Bypass enabled on segment: {name} (type: {bypass_type})")

            health_key = health.lower() if health.lower() in stats["health_reporting"] else "none"
            stats["health_reporting"][health_key] += 1

            stats["segments"].append({
                "name": name,
                "enabled": enabled,
                "domains": domains[:5],
                "ports": tcp_ports[:5],
                "bypass": bypass_type
            })

        print(f"  Total: {stats['total']}, Enabled: {stats['enabled']}, Disabled: {stats['disabled']}")
        print(f"  Bypass enabled: {stats['bypass_enabled']}")
        print(f"  Health reporting: {stats['health_reporting']}")
        return stats

    def audit_access_policies(self) -> dict[str, Any]:
        """Audit access policy configuration."""
        print("\n[3/5] Auditing Access Policies...")
        data = self._get("policySet/rules?policyType=ACCESS_POLICY")
        rules = data.get("list", [])

        stats = {
            "total": len(rules),
            "allow_rules": 0,
            "deny_rules": 0,
            "has_default_deny": False,
            "rules_without_conditions": 0,
            "rules_with_posture": 0,
            "rules": []
        }

        for rule in rules:
            name = rule.get("name", "unknown")
            action = rule.get("action", "UNKNOWN")
            conditions = rule.get("conditions", [])
            order = rule.get("order", 0)

            if action == "ALLOW":
                stats["allow_rules"] += 1
            elif action == "DENY":
                stats["deny_rules"] += 1

            if not conditions:
                stats["rules_without_conditions"] += 1
                print(f"  [WARN] Rule '{name}' has no conditions - overly permissive")

            # Check for device posture conditions
            has_posture = any(
                c.get("operands", [{}])[0].get("objectType") == "POSTURE_PROFILE"
                for c in conditions if c.get("operands")
            )
            if has_posture:
                stats["rules_with_posture"] += 1

            stats["rules"].append({
                "name": name, "action": action, "order": order,
                "conditions_count": len(conditions), "has_posture": has_posture
            })

        # Check for default deny rule (should be last rule with DENY action)
        if rules and rules[-1].get("action") == "DENY":
            stats["has_default_deny"] = True
        else:
            print("  [CRITICAL] No default deny rule found! All unlisted access may be permitted.")

        print(f"  Total rules: {stats['total']}")
        print(f"  Allow: {stats['allow_rules']}, Deny: {stats['deny_rules']}")
        print(f"  Rules with device posture: {stats['rules_with_posture']}")
        print(f"  Default deny: {'Yes' if stats['has_default_deny'] else 'NO - MISSING!'}")
        return stats

    def audit_server_groups(self) -> dict[str, Any]:
        """Audit server group configuration."""
        print("\n[4/5] Auditing Server Groups...")
        data = self._get("serverGroup")
        groups = data.get("list", [])

        stats = {
            "total": len(groups),
            "enabled": 0,
            "servers_total": 0,
            "groups": []
        }

        for group in groups:
            name = group.get("name", "unknown")
            enabled = group.get("enabled", False)
            servers = group.get("servers", [])

            if enabled:
                stats["enabled"] += 1
            stats["servers_total"] += len(servers)
            stats["groups"].append({
                "name": name, "enabled": enabled, "server_count": len(servers)
            })

        print(f"  Total groups: {stats['total']}, Enabled: {stats['enabled']}")
        print(f"  Total servers: {stats['servers_total']}")
        return stats

    def generate_report(self, connectors, segments, policies, server_groups) -> str:
        """Generate comprehensive ZPA audit report."""
        print("\n[5/5] Generating audit report...")
        now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")

        report = f"""
ZPA ZTNA Deployment Audit Report
{'=' * 55}
Customer ID: {self.customer_id}
Generated: {now}

1. APP CONNECTORS
   Total deployed:              {connectors['total']}
   Healthy:                     {connectors['healthy']}
   Unhealthy:                   {connectors['unhealthy']}
   Connector groups:            {len(connectors['groups'])}
   HA compliance (2+ per group): {'PASS' if all(v >= 2 for v in connectors['groups'].values()) else 'FAIL'}

2. APPLICATION SEGMENTS
   Total segments:              {segments['total']}
   Enabled:                     {segments['enabled']}
   Disabled:                    {segments['disabled']}
   With bypass enabled:         {segments['bypass_enabled']}
   Health reporting:            {segments['health_reporting']}

3. ACCESS POLICIES
   Total rules:                 {policies['total']}
   Allow rules:                 {policies['allow_rules']}
   Deny rules:                  {policies['deny_rules']}
   Default deny rule:           {'YES' if policies['has_default_deny'] else 'MISSING - CRITICAL'}
   Rules with device posture:   {policies['rules_with_posture']} / {policies['total']}

4. SERVER GROUPS
   Total groups:                {server_groups['total']}
   Total servers:               {server_groups['servers_total']}

5. RECOMMENDATIONS
"""
        recommendations = []
        if connectors['unhealthy'] > 0:
            recommendations.append(f"   - Fix {connectors['unhealthy']} unhealthy App Connector(s)")
        if not policies['has_default_deny']:
            recommendations.append("   - ADD DEFAULT DENY RULE immediately")
        if policies['rules_with_posture'] < policies['allow_rules']:
            gap = policies['allow_rules'] - policies['rules_with_posture']
            recommendations.append(f"   - Add device posture to {gap} allow rule(s)")
        if segments['bypass_enabled'] > 0:
            recommendations.append(f"   - Review {segments['bypass_enabled']} segment(s) with bypass enabled")
        if not recommendations:
            recommendations.append("   - No critical issues found")

        report += "\n".join(recommendations)
        return report


def main():
    if len(sys.argv) < 4:
        print("Usage: python process.py <client_id> <client_secret> <customer_id>")
        print("\nAudits ZPA deployment for connector health, segment coverage, and policy compliance.")
        sys.exit(1)

    auditor = ZPAAuditor(sys.argv[1], sys.argv[2], sys.argv[3])

    connectors = auditor.audit_app_connectors()
    segments = auditor.audit_application_segments()
    policies = auditor.audit_access_policies()
    server_groups = auditor.audit_server_groups()

    report = auditor.generate_report(connectors, segments, policies, server_groups)
    print(report)

    filename = f"zpa_audit_{datetime.now().strftime('%Y%m%d')}.txt"
    with open(filename, "w") as f:
        f.write(report)
    print(f"\nReport saved to: {filename}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Active breach containment agent for incident response operations."""

import json
import subprocess
import sys
from datetime import datetime


def block_ip_at_firewall(ip_address, chain="INPUT", comment="breach-containment"):
    """Block a C2 or malicious IP address using iptables."""
    cmd = [
        "iptables", "-A", chain, "-s", ip_address, "-j", "DROP",
        "-m", "comment", "--comment", comment,
    ]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        return {
            "action": "block_ip",
            "ip": ip_address,
            "success": result.returncode == 0,
            "error": result.stderr.strip() if result.returncode != 0 else None,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
    except Exception as e:
        return {"action": "block_ip", "ip": ip_address, "success": False, "error": str(e)}


def disable_ad_account(username, domain_controller=None):
    """Disable a compromised Active Directory account via PowerShell."""
    ps_cmd = f'Disable-ADAccount -Identity "{username}" -Confirm:$false'
    if domain_controller:
        ps_cmd += f' -Server "{domain_controller}"'
    cmd = ["powershell", "-Command", ps_cmd]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return {
            "action": "disable_account",
            "username": username,
            "success": result.returncode == 0,
            "error": result.stderr.strip() if result.returncode != 0 else None,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
    except Exception as e:
        return {"action": "disable_account", "username": username, "success": False, "error": str(e)}


def reset_ad_password(username, domain_controller=None):
    """Force password reset for a compromised AD account."""
    ps_cmd = (
        f'Set-ADAccountPassword -Identity "{username}" -Reset '
        f'-NewPassword (ConvertTo-SecureString -AsPlainText '
        f'"TempP@ss{datetime.now().strftime("%H%M%S")}!" -Force)'
    )
    if domain_controller:
        ps_cmd += f' -Server "{domain_controller}"'
    cmd = ["powershell", "-Command", ps_cmd]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return {
            "action": "reset_password",
            "username": username,
            "success": result.returncode == 0,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
    except Exception as e:
        return {"action": "reset_password", "username": username, "success": False, "error": str(e)}


def isolate_host_firewall(host_ip, management_ip=None):
    """Isolate a compromised host by blocking all traffic except management."""
    commands = []
    if management_ip:
        commands.append(
            ["iptables", "-A", "FORWARD", "-s", host_ip, "-d", management_ip, "-j", "ACCEPT"]
        )
        commands.append(
            ["iptables", "-A", "FORWARD", "-s", management_ip, "-d", host_ip, "-j", "ACCEPT"]
        )
    commands.append(["iptables", "-A", "FORWARD", "-s", host_ip, "-j", "DROP"])
    commands.append(["iptables", "-A", "FORWARD", "-d", host_ip, "-j", "DROP"])

    results = []
    for cmd in commands:
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            results.append({"cmd": " ".join(cmd), "success": r.returncode == 0})
        except Exception as e:
            results.append({"cmd": " ".join(cmd), "success": False, "error": str(e)})

    return {
        "action": "isolate_host",
        "host_ip": host_ip,
        "management_ip": management_ip,
        "results": results,
        "timestamp": datetime.utcnow().isoformat() + "Z",
    }


def block_smb_lateral_movement():
    """Block SMB (port 445) between server VLANs to prevent lateral movement."""
    cmd = ["iptables", "-A", "FORWARD", "-p", "tcp", "--dport", "445", "-j", "DROP"]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        return {
            "action": "block_smb",
            "success": result.returncode == 0,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
    except Exception as e:
        return {"action": "block_smb", "success": False, "error": str(e)}


def sinkhole_domain(domain, sinkhole_ip="127.0.0.1", hosts_file="/etc/hosts"):
    """Add DNS sinkhole entry for a C2 domain."""
    entry = f"{sinkhole_ip}\t{domain}\t# breach-containment {datetime.utcnow().isoformat()}"
    try:
        with open(hosts_file, "r") as f:
            existing = f.read()
        if domain in existing:
            return {"action": "sinkhole", "domain": domain, "status": "already_sinkholed"}
        with open(hosts_file, "a") as f:
            f.write("\n" + entry + "\n")
        return {
            "action": "sinkhole",
            "domain": domain,
            "sinkhole_ip": sinkhole_ip,
            "success": True,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
    except Exception as e:
        return {"action": "sinkhole", "domain": domain, "success": False, "error": str(e)}


def collect_volatile_evidence(host="localhost"):
    """Collect volatile system data from a compromised host for forensics."""
    evidence = {}
    commands = {
        "processes": ["ps", "auxww"],
        "network_connections": ["ss", "-tunap"],
        "logged_users": ["who"],
        "routing_table": ["ip", "route", "show"],
        "arp_table": ["arp", "-an"],
        "open_files": ["lsof", "-i", "-P"],
    }
    for name, cmd in commands.items():
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            evidence[name] = r.stdout.strip()
        except Exception as e:
            evidence[name] = f"Error: {e}"

    return {
        "action": "collect_evidence",
        "host": host,
        "evidence": evidence,
        "timestamp": datetime.utcnow().isoformat() + "Z",
    }


def generate_containment_report(incident_id, actions_taken):
    """Generate a structured containment status report."""
    return {
        "report_type": "CONTAINMENT_STATUS",
        "incident_id": incident_id,
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "status": "CONTAINED",
        "actions_taken": actions_taken,
        "validation_pending": [
            "Confirm C2 beacons ceased",
            "Verify disabled accounts produce auth failures",
            "Check no new lateral movement attempts",
        ],
    }


if __name__ == "__main__":
    action = sys.argv[1] if len(sys.argv) > 1 else "help"
    if action == "block-ip" and len(sys.argv) > 2:
        print(json.dumps(block_ip_at_firewall(sys.argv[2]), indent=2))
    elif action == "disable-account" and len(sys.argv) > 2:
        print(json.dumps(disable_ad_account(sys.argv[2]), indent=2))
    elif action == "isolate-host" and len(sys.argv) > 2:
        mgmt = sys.argv[3] if len(sys.argv) > 3 else None
        print(json.dumps(isolate_host_firewall(sys.argv[2], mgmt), indent=2))
    elif action == "block-smb":
        print(json.dumps(block_smb_lateral_movement(), indent=2))
    elif action == "sinkhole" and len(sys.argv) > 2:
        print(json.dumps(sinkhole_domain(sys.argv[2]), indent=2))
    elif action == "collect-evidence":
        print(json.dumps(collect_volatile_evidence(), indent=2))
    else:
        print("Usage: agent.py [block-ip <ip>|disable-account <user>|isolate-host <ip> [mgmt_ip]|block-smb|sinkhole <domain>|collect-evidence]")
